    "contenu": "<p>Le <b>past continuous</b> décrit une action qui était <b>en cours</b> à un moment précis du passé. Il se forme avec le prétérit de be (was / were) et le participe présent (-ing).</p><div class='definition'><b>Formule affirmative :</b> sujet + was/were + verbe-ing. Ex. : I was reading at six o'clock. They were playing football.<br><b>was</b> avec I, he, she, it ; <b>were</b> avec you, we, they.<br><b>Négative :</b> wasn't / weren't + verbe-ing. Ex. : She wasn't sleeping.<br><b>Question :</b> Was/Were + sujet + verbe-ing ? Ex. : Were you studying at noon?</div><div class='exemple'><b>Exemple :</b> <i>When the teacher came in, we were talking.</i> (Quand le professeur est entré, nous étions en train de parler.) La conversation était en cours quand l'action du professeur s'est produite.</div><div class='astuce'><b>Astuce :</b> le past continuous s'utilise souvent avec le past simple. Le past continuous décrit le décor, le past simple raconte l'événement qui interrompt. Mots-clés utiles : while (pendant que), when (quand).</div>",
