    "contenu": "<p>Une phrase <b>conditionnelle</b> exprime une condition et sa conséquence. On distingue plusieurs types ; les deux plus étudiés au collège sont le type 1 (réel) et le type 2 (imaginaire).</p><div class='definition'><b>Type 1 (réel, avenir possible) :</b> if + present simple, will + verbe. Ex. : If it rains, we will stay at home.<br><b>Type 2 (irréel, hypothèse peu probable) :</b> if + past simple, would + verbe. Ex. : If I had money, I would buy a bicycle.<br><b>Important :</b> le if-clause peut être placé avant ou après la conséquence. Une virgule sépare les deux quand la condition vient en premier.</div><div class='exemple'><b>Exemple :</b> <i>If you study hard, you will pass the BEPC.</i> (Si tu travailles bien, tu réussiras le BEPC.) Type 1 : la situation est réelle et possible.</div><div class='astuce'><b>Astuce :</b> dans le if-clause, on n'utilise jamais will au type 1. On écrit « if it rains », et non « if it will rain ».</div>",
