    "duree": "40 min",
    "contenu": "<p>La <b>voix passive</b> met en valeur l'action subie par le sujet, ou lorsque l'agent (la personne qui fait l'action) est inconnu ou sans importance. Elle se forme avec be + participe passé.</p><div class='definition'><b>Présent passif :</b> am/is/are + participe passé. Ex. : Cassava is grown in Cameroon.<br><b>Passé simple passif :</b> was/were + participe passé. Ex. : The letter was written yesterday.<br><b>Négative :</b> ajoute not après be. Ex. : The door isn't closed.<br><b>Agent :</b> on introduit l'agent avec by. Ex. : The house was built by my grandfather.</div><div class='exemple'><b>Exemple :</b> <i>Active : The farmers grow maize. Passive : Maize is grown by the farmers.</i> Le sujet devient maize, et le complément devient l'agent introduit par by.</div><div class='astuce'><b>Astuce :</b> pour passer de l'actif au passif : le complément d'objet devient sujet, on met le verbe be au temps du verbe actif, puis on met le verbe au participe passé.</div>",
