    "duree": "40 min",
    "contenu": "<p>Pour écrire une lettre ou un courriel en anglais, il faut respecter une structure et un registre adaptés au destinataire. On distingue la lettre formelle (à un professeur, une administration) et la lettre informelle (à un ami).</p><div class='definition'><b>Structure :</b> adresse de l'expéditeur, date, formule d'appel (Dear Mr Mbarga, / Dear Sarah,), corps du message, formule de politesse (Yours sincerely / Best wishes), signature.<br><b>Registre formel :</b> phrases complètes, pas de contractions (I am, I do not), formules polies (I would be grateful if...).<br><b>Registre informel :</b> contractions et expressions familières (I'm, can't, Hi there).<br><b>Les formules de politesse :</b> Yours sincerely (si le nom est connu), Yours faithfully (si le nom est inconnu).</div><div class='exemple'><b>Exemple :</b> <i>Dear Madam, I am writing to apply for the post of secretary. I would be grateful if you could send me more information. Yours faithfully, Paul Nkeng.</i></div><div class='astuce'><b>Astuce :</b> adapte le registre au destinataire. Pour une lettre à un professeur ou à une administration, évite les contractions et les expressions familières.</div>",
