    "id": "e3-constitution-cameroun",
    "titre": "La Constitution et l'organisation de l'État au Cameroun",
    "duree": "40 min",
    "contenu": "<p>La <b>Constitution</b> est la loi fondamentale d'un État. Elle organise les pouvoirs publics, définit les droits et les devoirs des citoyens et fixe les règles du jeu démocratique.</p><div class='definition'><b>Le Cameroun</b> est une république unitaire et décentralisée. Il est organisé en régions, départements, arrondissements et communes.<br><b>La décentralisation</b> consiste à transférer certaines compétences de l'État central vers les collectivités locales, élues par la population.<br><b>Le chef de l'État</b> est le Président de la République, élu au suffrage universel direct pour un mandat de sept ans renouvelable.<br><b>Le Premier ministre</b> dirige le Gouvernement.<br><b>La séparation des pouvoirs</b> répartit les fonctions entre le pouvoir exécutif, le pouvoir législatif et le pouvoir judiciaire.</div><p>Le respect de la Constitution est essentiel : aucune loi ne doit la contredire. Le citoyen peut s'informer sur ses droits et ses devoirs grâce à ce texte.</p><div class='exemple'><b>Exemple :</b> le Président de la République est élu au suffrage universel direct : chaque citoyen inscrit sur les listes électorales peut voter. C'est l'application du principe démocratique.</div><div class='astuce'><b>Astuce :</b> retiens les trois niveaux : l'État central (gouvernement), les régions et les communes. La décentralisation rapproche les décisions des citoyens.</div>",
