    "duree": "40 min",
    "contenu": "<p>Un enfant est une personne mineure, c'est-à-dire âgée de moins de 18 ans. Il bénéficie d'une <b>protection juridique</b> particulière, qui garantit ses droits et son bien-être.</p><div class='definition'><b>La minorité</b> est la période de la vie avant 18 ans, pendant laquelle l'enfant n'a pas la pleine capacité juridique et est sous la responsabilité de ses parents ou de son tuteur.<br><b>La protection de l'enfance</b> regroupe les lois et institutions qui défendent les enfants contre la maltraitance, l'exploitation et l'abandon.<br><b>Le tribunal pour enfants</b> juge les mineurs et privilégie l'éducation et la réinsertion.<br><b>Le travail des enfants</b> est interdit lorsqu'il menace leur santé, leur éducation ou leur développement.</div><p>La justice des mineurs cherche d'abord à éduquer et réinsérer, plutôt qu'à punir de manière sévère.</p><div class='exemple'><b>Exemple :</b> un enfant qui vole par nécessité n'est pas traité comme un adulte : le juge pour enfants cherche des solutions éducatives et sociales, comme un suivi ou un placement adapté.</div><div class='astuce'><b>Astuce :</b> retiens que la justice des mineurs vise la protection et l'éducation. C'est un principe important pour comprendre les droits de l'enfant.</div>",
