    "id": "e3-integration-diversite",
    "titre": "Unité nationale et diversité culturelle au Cameroun",
    "duree": "40 min",
    "contenu": "<p>Le Cameroun est un pays très diversifié : il compte plus de deux cent cinquante groupes ethniques, des langues variées et deux langues officielles, le français et l'anglais. Cette diversité est une richesse, et l'<b>unité nationale</b> est un objectif constant de l'État.</p><div class='definition'><b>L'unité nationale</b> est le sentiment d'appartenance commune à une même nation, malgré les différences d'origine, de langue ou de religion.<br><b>La diversité culturelle</b> désigne la richesse des cultures, des langues, des traditions et des modes de vie présents dans un même pays.<br><b>Le bilinguisme officiel</b> reconnaît le français et l'anglais comme langues officielles.<br><b>La cohésion sociale</b> désigne la solidarité entre les membres d'une société.</div><p>Pour préserver l'unité nationale, il faut respecter les différences, lutter contre le tribalisme et les discriminations, et valoriser le patrimoine commun.</p><div class='exemple'><b>Exemple :</b> lors de la fête nationale du 20 mai, les Camerounais de toutes les régions et de toutes les langues célèbrent ensemble le pays. C'est un moment de cohésion nationale.</div><div class='astuce'><b>Astuce :</b> retiens la formule : diversité pour la richesse, unité pour la cohésion. Les deux vont ensemble, et l'une ne doit pas écraser l'autre.</div>",
