    "id": "eps3-planification-entrainement",
    "titre": "Planifier son entraînement : principes et progressivité",
    "duree": "40 min",
    "contenu": "<p>Pour progresser durablement, un sportif ne s'entraîne pas au hasard : il <b>planifie</b> ses séances. Un entraînement efficace respecte des principes simples qui permettent d'améliorer la performance tout en protégeant le corps.</p><div class='definition'><b>La charge d'entraînement</b> est la quantité et l'intensité d'un effort : nombre de répétitions, durée, rythme.<br><b>La surcompensation</b> est le phénomène par lequel le corps, après un effort suivi d'un repos suffisant, s'adapte et devient plus performant.<br><b>La récupération</b> est la période de repos qui permet au corps de se reconstruire entre deux séances.<br><b>La progressivité</b> consiste à augmenter la charge petit à petit, pour éviter le surmenage et les blessures.<br><b>La spécificité</b> consiste à entraîner les qualités utiles à l'activité pratiquée.</div><p>Une bonne planification alterne les séances intenses et les séances légères, et prévoit des jours de repos.</p><div class='exemple'><b>Exemple :</b> un coureur qui s'entraîne trois fois par semaine : une séance de vitesse, une séance d'endurance et une séance légère de récupération. Le repos du lendemain permet la surcompensation.</div><div class='astuce'><b>Astuce :</b> ne jamais enchaîner deux séances très intenses sans repos. Un programme sain alterne charge et récupération, comme les marches d'un escalier.</div>",
