    "titre": "L'athlétisme : le demi-fond et la gestion de l'effort",
    "duree": "40 min",
    "contenu": "<p>Le <b>demi-fond</b> regroupe les courses de 800 m et 1 500 m. Ces épreuves combinent vitesse et endurance : il faut savoir doser son effort sur toute la distance.</p><div class='definition'><b>Le départ</b> est la phase initiale : on prend une bonne position et on accélère sans s'épuiser.<br><b>L'allure</b> est la vitesse de course maintenue sur la distance.<br><b>La gestion de l'effort</b> consiste à répartir son énergie sur toute la course, en gardant de la réserve pour la fin.<br><b>Le dernier tour</b> est souvent le moment d'accélérer, si l'énergie le permet.<br><b>Les splits</b> désigne le temps réalisé sur chaque tour ou chaque portion, pour contrôler son allure.</div><p>Partir trop vite est l'erreur la plus fréquente : on s'épuise avant l'arrivée. Une course régulière, avec une accélération maîtrisée, donne souvent les meilleurs résultats.</p><div class='exemple'><b>Exemple :</b> sur 800 m (deux tours de piste), un élève court le premier tour à allure régulière, garde de l'énergie, puis accélère dans les derniers mètres. Il évite de partir à fond.</div><div class='astuce'><b>Astuce :</b> pour un 800 m, pense à trois phases : un départ contrôlé, une allure stable au milieu, et une accélération finale. Ne grille pas ta réserve trop tôt.</div>",
