    "id": "eps3-securite-preparation-physique",
    "titre": "Échauffement spécifique, hydratation et prévention des blessures",
    "duree": "40 min",
    "contenu": "<p>Avant une compétition ou un entraînement intense, la <b>préparation</b> du corps réduit fortement le risque de blessure. Elle comprend un échauffement adapté, une bonne hydratation et une attention particulière à la fatigue.</p><div class='definition'><b>L'échauffement spécifique</b> reprend les gestes de l'activité pratiquée, à intensité progressive (par exemple, des accélérations courtes avant un sprint).<br><b>L'hydratation</b> consiste à boire régulièrement avant, pendant et après l'effort, surtout par forte chaleur.<br><b>La prévention des blessures</b> repose sur l'échauffement, la progressivité, le repos et une tenue adaptée.<br><b>La fatigue</b> est un signal d'alerte : une fatigue inhabituelle, des douleurs persistantes ou une baisse de performance doivent faire réfléchir.</div><p>Les crampes, les élongations et les tendinites sont des blessures fréquentes qui peuvent être évitées par une bonne préparation.</p><div class='exemple'><b>Exemple :</b> avant un 800 m, un élève fait un footing léger, des montées de genoux, des accélérations de 50 m et des étirements doux. Il boit de l'eau régulièrement pendant la journée.</div><div class='astuce'><b>Astuce :</b> si une douleur persiste plus de quelques jours malgré le repos, ne continue pas à t'entraîner : parles-en à un adulte ou à un médecin.</div>",
