    "contenu": "<p><b>Conduite de balle :</b> action de faire avancer le ballon avec le pied, en gardant le contrôle. On touche le ballon avec l'intérieur ou l'extérieur du pied, sans regarder uniquement le ballon.</p>\n<p><b>Passe :</b> envoi du ballon à un partenaire. La passe à l'intérieur du pied est la plus précise sur de courtes distances.</p>\n<p><b>Conseil :</b> lève la tête avant de passer pour voir les partenaires démarqués, c'est-à-dire libres de tout adversaire.</p>\n<p><b>Exemple :</b> pendant un match scolaire, un joueur conduit le ballon sur quelques mètres, puis fait une passe à l'intérieur du pied à un coéquipier démarqué.</p>",
