    "duree": "40 min",
    "contenu": "<p>La <b>mondialisation</b> est le processus d'intensification des échanges de biens, de services, de capitaux, d'informations et de personnes à l'échelle du monde. Elle rend les économies et les sociétés de plus en plus interdépendantes.</p><div class='definition'><b>Une firme multinationale</b> est une entreprise qui produit ou vend dans plusieurs pays.<br><b>La délocalisation</b> consiste à transférer une activité de production vers un pays où la main-d'œuvre coûte moins cher.<br><b>Les flux</b> désignent les échanges de marchandises, de capitaux, d'informations et de personnes entre les territoires.<br><b>L'interdépendance</b> est le fait que les pays dépendent les uns des autres pour leur économie.</div><p>La mondialisation profite surtout aux pays et aux régions bien connectés aux réseaux de transport et de communication. Elle accentue aussi des inégalités entre régions et entre groupes sociaux.</p><div class='exemple'><b>Exemple :</b> un téléphone conçu aux États-Unis peut être assemblé en Asie avec des composants venus de plusieurs pays, puis vendu en Afrique. Ce produit illustre l'interdépendance mondiale.</div><div class='astuce'><b>Astuce :</b> pour expliquer la mondialisation, utilise trois idées : les flux (ce qui circule), les acteurs (firmes, États, individus) et les inégalités (qui en profite, qui en souffre).</div>",
