    "duree": "40 min",
    "contenu": "<p>L'Afrique regroupe plus de cinquante États et une population jeune et en forte croissance. Elle connaît des progrès importants, mais elle fait face à de nombreux défis de développement.</p><div class='definition'><b>Les défis</b> regroupent la pauvreté, l'accès à l'éducation et à la santé, les infrastructures insuffisantes et la dépendance aux matières premières.<br><b>L'intégration régionale</b> désigne la coopération économique et politique entre pays voisins, par exemple dans la CEMAC (Afrique centrale), dont fait partie le Cameroun.<br><b>Les ressources</b> de l'Afrique sont nombreuses : pétrole, gaz, minerais, forêts, terres agricoles.<br><b>L'urbanisation</b> rapide accentue les besoins en logements, eau et transports.</div><p>Pour réduire les inégalités, les pays africains cherchent à diversifier leur économie, à transformer sur place leurs matières premières et à développer les infrastructures.</p><div class='exemple'><b>Exemple :</b> la CEMAC réunit six pays d'Afrique centrale, dont le Cameroun, pour coordonner la monnaie commune (le franc CFA) et favoriser les échanges.</div><div class='astuce'><b>Astuce :</b> pour parler du développement de l'Afrique, pense à trois niveaux : les atouts (ressources, jeunesse), les défis (pauvreté, infrastructures) et les stratégies (intégration, diversification).</div>",
