    "id": "g3-environnement-changement-climatique",
    "titre": "Environnement et changement climatique",
    "duree": "40 min",
    "contenu": "<p>Le <b>changement climatique</b> désigne l'évolution du climat à l'échelle de la planète, principalement due aux activités humaines. Il se manifeste par une hausse des températures moyennes et des modifications des précipitations.</p><div class='definition'><b>L'effet de serre</b> est un phénomène naturel : certains gaz (dioxyde de carbone, méthane) retiennent une partie de la chaleur du Soleil. Son renforcement par les activités humaines accentue le réchauffement.<br><b>Les gaz à effet de serre</b> sont émis notamment par la combustion d'énergies fossiles, la déforestation et l'élevage.<br><b>L'adaptation</b> consiste à s'ajuster aux conséquences du changement climatique. <b>L'atténuation</b> consiste à réduire les émissions de gaz à effet de serre.<br><b>La déforestation</b> réduit la capacité de la forêt à absorber le dioxyde de carbone.</div><p>Au Cameroun, les conséquences se font sentir sur l'agriculture, la ressource en eau et les zones côtières.</p><div class='exemple'><b>Exemple :</b> une saison des pluies plus irrégulière peut retarder les semis de maïs ou d'arachide. Les agriculteurs doivent alors adapter leurs calendriers et leurs variétés.</div><div class='astuce'><b>Astuce :</b> retiens la différence : l'adaptation subit le changement, l'atténuation le limite. Les deux sont nécessaires.</div>",
