    "duree": "30 min",
    "contenu": "<p><b>CEMAC (Communauté économique et monétaire de l'Afrique centrale) :</b> organisation régionale qui regroupe six pays d'Afrique centrale, dont le Cameroun, pour faciliter les échanges et partager une monnaie commune.</p>\n<p>Les pays membres partagent le franc CFA (XAF), géré par la Banque des États de l'Afrique centrale (BEAC). Cela facilite les paiements et les échanges entre les pays membres, sans conversion monétaire.</p>\n<p>Le Cameroun est un pays central de la zone : son port de Douala et ses routes facilitent le transit des marchandises vers le Tchad, la République centrafricaine et le Congo.</p>\n<p><b>Intégration régionale :</b> rapprochement économique entre des pays voisins, qui supprime peu à peu les barrières douanières.</p>",
