    "duree": "40 min",
    "contenu": "<p>De 1914 à 1918, les grandes puissances européennes s'affrontent dans la <b>Première Guerre mondiale</b>. C'est le premier conflit à l'échelle mondiale : des combattants venus de nombreux pays, dont des soldats africains, y participent.</p><div class='definition'><b>Les deux camps :</b> la Triple-Entente (France, Royaume-Uni, Russie, puis États-Unis en 1917) face à la Triplice (Allemagne, Autriche-Hongrie, Empire ottoman).<br><b>La guerre de tranchées</b> : les soldats s'enterrent dans des tranchées sur le front, où les combats sont longs et meurtriers.<br><b>L'armistice</b> est la suspension des combats, signée le 11 novembre 1918.<br><b>Le traité de Versailles</b> (1919) impose des sanctions lourdes à l'Allemagne.</div><p>Le conflit fait plus de 9 millions de morts militaires. Il laisse une Europe affaiblie et des peuples colonisés mobilisés, dont beaucoup d'Africains.</p><div class='exemple'><b>Exemple :</b> au Cameroun, la campagne militaire de 1914 à 1916 met fin à la domination allemande sur le territoire. Des tirailleurs africains participent aux combats en Europe.</div><div class='astuce'><b>Astuce :</b> retiens la chronologie : déclenchement en 1914, armistice le 11 novembre 1918, traité de Versailles en 1919.</div>",
