    "duree": "40 min",
    "contenu": "<p>La <b>Seconde Guerre mondiale</b> (1939-1945) oppose les puissances de l'Axe (Allemagne nazie, Italie, Japon) aux Alliés (France, Royaume-Uni, URSS, États-Unis). Elle est le conflit le plus meurtrier de l'histoire.</p><div class='definition'><b>La Shoah</b> (ou génocide des Juifs) est l'extermination systématique de six millions de Juifs par le régime nazi.<br><b>Le régime nazi</b> est un régime totalitaire dirigé par Hitler, fondé sur le racisme et l'expansion territoriale.<br><b>La résistance</b> désigne l'opposition à l'occupation et au régime nazi, sous des formes variées.<br><b>L'ONU</b> est créée en 1945 pour maintenir la paix et éviter une nouvelle guerre mondiale.</div><p>La guerre se termine en Europe le 8 mai 1945 et dans le Pacifique en août 1945.</p><div class='exemple'><b>Exemple :</b> le camp d'Auschwitz, en Pologne, est le symbole de la Shoah. Il rappelle la nécessité de défendre les droits humains.</div><div class='astuce'><b>Astuce :</b> retiens que la Seconde Guerre mondiale a donné naissance à l'ONU et à la Déclaration universelle des droits de l'homme en 1948. C'est l'origine des droits humains modernes.</div>",
