    "id": "h3-decolonisation-cameroun",
    "titre": "La décolonisation africaine et l'indépendance du Cameroun",
    "duree": "40 min",
    "contenu": "<p>Après 1945, les peuples colonisés réclament leur indépendance. Entre 1957 et 1960, la plupart des colonies d'Afrique deviennent indépendantes : c'est la <b>décolonisation</b>.</p><div class='definition'><b>La décolonisation</b> est le processus par lequel une colonie accède à l'indépendance politique.<br><b>L'UPC</b> (Union des populations du Cameroun), fondée en 1948, réclame l'indépendance immédiate. Son leader, Ruben Um Nyobè, est assassiné en 1958.<br><b>L'indépendance du Cameroun</b> française est proclamée le 1er janvier 1960. Ahmadou Ahidjo devient le premier président.<br><b>La réunification</b> de 1961 rassemble le Cameroun francophone et le Cameroun britannique méridional, après un référendum.</div><p>La décolonisation s'accompagne de tensions : le mouvement nationaliste camerounais a été durement réprimé, et de nombreuses questions restent débattues par les historiens.</p><div class='exemple'><b>Exemple :</b> au Cameroun, la lutte pour l'indépendance a été menée par des mouvements politiques et des leaders comme Um Nyobè. Elle a conduit à l'indépendance de 1960, puis à la réunification de 1961.</div><div class='astuce'><b>Astuce :</b> retiens la chronologie : UPC (1948), indépendance (1er janvier 1960), réunification (1961). Pour l'Afrique, la vague des indépendances est surtout située entre 1957 et 1960.</div>",
