    "contenu": "<p>De 1947 à 1991, le monde est divisé en deux blocs rivaux : le <b>bloc de l'Ouest</b>, dirigé par les États-Unis, et le <b>bloc de l'Est</b>, dirigé par l'URSS. Cette rivalité s'appelle la <b>guerre froide</b> : il n'y a pas d'affrontement militaire direct entre les deux superpuissances, mais une course aux armements et de nombreux conflits par pays interposés.</p><div class='definition'><b>Le bloc de l'Ouest</b> est organisé autour des États-Unis, avec l'OTAN et l'économie de marché.<br><b>Le bloc de l'Est</b> est organisé autour de l'URSS, avec le pacte de Varsovie et un régime communiste.<br><b>La course aux armements</b> est la compétition entre les deux blocs pour posséder les armes les plus puissantes, dont l'arme nucléaire.<br><b>Le mur de Berlin</b> (1961-1989) sépare Berlin-Est et Berlin-Ouest, symbole de la division du monde.</div><p>La guerre froide prend fin avec la chute du mur de Berlin en 1989 et la dislocation de l'URSS en 1991.</p><div class='exemple'><b>Exemple :</b> lors de la guerre de Corée (1950-1953), les deux blocs s'affrontent indirectement, sans que les États-Unis et l'URSS se combattent directement.</div><div class='astuce'><b>Astuce :</b> retiens : guerre froide = affrontement indirect entre deux superpuissances, sans guerre directe entre elles. Pense aux mots-clés : bloc, course aux armements, mur de Berlin.</div>",
