    "contenu": "<p><b>Mot de passe solide :</b> long (au moins 10 caractères), avec des lettres, des chiffres et des symboles. Il ne doit pas être un mot du dictionnaire ni une date de naissance.</p>\n<p><b>Ne partage jamais tes mots de passe</b>, même avec un ami. Utilise un mot de passe différent pour chaque compte important.</p>\n<p><b>Hameçonnage (phishing) :</b> message qui imite une banque, un service ou un ami pour voler tes informations. Méfie-toi des liens inattendus qui demandent ton mot de passe.</p>\n<p><b>Exemple :</b> un message « Votre compte sera bloqué, cliquez ici » demande un mot de passe. C'est une tentative d'hameçonnage : ne clique pas et vérifie auprès du service officiel.</p>",
