    "id": "m3-statistiques",
    "titre": "Statistiques : moyenne, médiane et étendue",
    "duree": "40 min",
    "contenu": "<p>Les <b>statistiques</b> permettent de résumer une série de données. Les indicateurs les plus utilisés sont la moyenne, la médiane et l'étendue.</p><div class='definition'><b>La moyenne</b> est la somme des valeurs divisée par leur nombre.<br><b>La médiane</b> est la valeur centrale d'une série rangée dans l'ordre : la moitié des valeurs est inférieure, l'autre moitié supérieure. Si la série a un nombre pair de valeurs, la médiane est la moyenne des deux valeurs centrales.<br><b>L'étendue</b> est la différence entre la plus grande et la plus petite valeur.<br><b>L'effectif</b> est le nombre de fois qu'une valeur apparaît.</div><div class='exemple'><b>Exemple :</b> notes d'un élève : 8 ; 12 ; 10 ; 14 ; 6. Moyenne = (8 + 12 + 10 + 14 + 6) ÷ 5 = 10. Série rangée : 6 ; 8 ; 10 ; 12 ; 14, médiane = 10. Étendue = 14 − 6 = 8.</div><div class='astuce'><b>Astuce :</b> la médiane est moins sensible aux valeurs extrêmes que la moyenne. Elle est donc utile quand une valeur très différente fausse la moyenne.</div>",
    "exercices": [
     {
      "q": "Calcule la moyenne de 4 ; 8 ; 10 ; 6.",
      "r": "(4 + 8 + 10 + 6) ÷ 4 = 28 ÷ 4 = 7.",
      "indice": "Additionne puis divise par le nombre de valeurs."
     },
     {
      "q": "Calcule la médiane de 9 ; 3 ; 7 ; 5 ; 11.",
      "r": "Série rangée : 3 ; 5 ; 7 ; 9 ; 11. Médiane = 7.",
      "indice": "Range d'abord les valeurs."
     },
     {
      "q": "Calcule la médiane de 2 ; 4 ; 6 ; 8.",
      "r": "(4 + 6) ÷ 2 = 5.",
      "indice": "Nombre pair de valeurs : prends les deux valeurs centrales."
     },
     {
      "q": "Calcule l'étendue de 12 ; 5 ; 20 ; 9.",
      "r": "20 − 5 = 15.",
      "indice": "Différence entre le maximum et le minimum."
     },
     {
      "q": "Une valeur de 100 apparaît dans la série 10 ; 12 ; 11 ; 100. Pourquoi la médiane est-elle plus pertinente que la moyenne ?",
      "r": "La valeur 100 tire la moyenne vers le haut ; la médiane reste représentative du centre des données.",
      "indice": "Pense à l'influence des valeurs extrêmes."
     }
    ],
