    "titre": "La structure de l'atome : noyau, électrons et neutralité",
    "duree": "40 min",
    "contenu": "<p>L'<b>atome</b> est constitué d'un <b>noyau</b> très petit, situé au centre, entouré d'un nuage d'<b>électrons</b>. Presque toute la masse de l'atome est concentrée dans le noyau.</p><div class='definition'><b>Le noyau</b> contient des <b>protons</b> (charge électrique positive, notée +) et des <b>neutrons</b> (sans charge électrique).<br><b>Les électrons</b> portent une charge négative (notée −). Ils sont très légers par rapport au noyau.<br><b>Le numéro atomique Z</b> est le nombre de protons du noyau. Il caractérise l'élément chimique.<br><b>Le nombre de masse A</b> est la somme des protons et des neutrons : A = Z + N.<br><b>Un atome est électriquement neutre</b> : il possède autant d'électrons que de protons.</div><div class='exemple'><b>Exemple :</b> l'atome de carbone a Z = 6. Il possède 6 protons, 6 électrons, et généralement 6 neutrons, donc A = 12.</div><div class='astuce'><b>Astuce :</b> le numéro atomique Z donne tout : nombre de protons, et donc nombre d'électrons dans un atome neutre. Si tu connais Z, tu connais la nature de l'élément.</div>",
