    "duree": "40 min",
    "contenu": "<p>Le <b>tableau périodique</b> classe tous les éléments chimiques connus. Chaque élément y est représenté par une case contenant son symbole, son numéro atomique et sa masse.</p><div class='definition'><b>Les lignes</b> du tableau s'appellent les <b>périodes</b>.<br><b>Les colonnes</b> s'appellent les <b>familles</b> : les éléments d'une même colonne ont des propriétés chimiques voisines.<br><b>Les gaz nobles</b> (hélium He, néon Ne, argon Ar) forment la dernière colonne. Ils sont très peu réactifs.<br><b>Les métaux alcalins</b> (lithium Li, sodium Na, potassium K) forment la première colonne. Ils réagissent facilement avec l'eau.</div><p>Le classement suit le numéro atomique : on range les éléments par ordre croissant de Z.</p><div class='exemple'><b>Exemple :</b> le sodium (Na) et le potassium (K) sont dans la même colonne. Ils réagissent tous deux de manière vive avec l'eau, car ils appartiennent à la même famille.</div><div class='astuce'><b>Astuce :</b> pour retenir la première colonne, pense aux métaux alcalins : ils ont un électron de plus que le gaz noble qui les précède et réagissent très facilement.</div>",
