    "titre": "La loi d'Ohm : tension, intensité et résistance",
    "duree": "40 min",
    "contenu": "<p>Dans un circuit électrique, trois grandeurs sont liées : la <b>tension</b> U, l'<b>intensité</b> I et la <b>résistance</b> R. La relation entre elles est la <b>loi d'Ohm</b>.</p><div class='definition'><b>La tension U</b> est la différence de potentiel entre deux bornes d'un dipôle. Elle s'exprime en volt (V).<br><b>L'intensité I</b> est le débit de charges électriques qui circulent. Elle s'exprime en ampère (A).<br><b>La résistance R</b> mesure l'opposition d'un dipôle au passage du courant. Elle s'exprime en ohm (Ω).<br><b>Loi d'Ohm :</b> U = R × I. On en déduit R = U ÷ I et I = U ÷ R.</div><div class='exemple'><b>Exemple :</b> une lampe de résistance R = 10 Ω est alimentée sous U = 6 V. L'intensité est I = U ÷ R = 6 ÷ 10 = 0,6 A.</div><div class='astuce'><b>Astuce :</b> pour retrouver la formule, fais le triangle U en haut, R et I en bas. Cache la grandeur recherchée : tu vois l'opération à faire.</div>",
