    "titre": "La réflexion de la lumière sur les miroirs",
    "duree": "40 min",
    "contenu": "<p>Lorsque la lumière rencontre une surface lisse et polie, comme un miroir, elle est <b>réfléchie</b>. Le miroir renvoie la lumière dans une direction précise, selon des lois simples.</p><div class='definition'><b>Le rayon incident</b> est le rayon qui arrive sur le miroir.<br><b>Le rayon réfléchi</b> est le rayon qui repart du miroir.<br><b>La normale</b> est la droite perpendiculaire au miroir au point d'impact.<br><b>Première loi :</b> le rayon incident, le rayon réfléchi et la normale sont dans un même plan.<br><b>Deuxième loi :</b> l'angle d'incidence est égal à l'angle de réflexion (i = r), mesurés par rapport à la normale.</div><div class='exemple'><b>Exemple :</b> un rayon arrive sur un miroir avec un angle d'incidence de 30° par rapport à la normale. Il repart avec un angle de réflexion de 30°, de l'autre côté de la normale.</div><div class='astuce'><b>Astuce :</b> mesure toujours les angles par rapport à la normale, jamais par rapport au miroir. C'est l'erreur la plus fréquente.</div>",
