    "duree": "40 min",
    "contenu": "<p>La Terre est constituée de plusieurs couches. La croûte terrestre est découpée en <b>plaques lithosphériques</b> qui se déplacent lentement. Leurs mouvements provoquent les <b>séismes</b> et une partie de l'<b>activité volcanique</b>.</p><div class='definition'><b>Un séisme</b> est une secousse brutale de la Terre, due à la rupture de roches en profondeur, le long d'une faille. Son point de départ est le <b>foyer</b> ; le point situé à la surface au-dessus est l'<b>épicentre</b>.<br><b>Un volcan</b> est un relief formé par l'accumulation de matériaux (laves, cendres) émis par une cheminée volcanique.<br><b>La lave</b> est le magma qui arrive en surface.<br><b>Une dorsale océanique</b> est une chaîne de volcans sous-marins où deux plaques s'écartent.</div><p>Les zones de forte activité sismique et volcanique se trouvent surtout aux limites des plaques.</p><div class='exemple'><b>Exemple :</b> le mont Cameroun, au sud-ouest du pays, est un volcan actif situé sur une ligne volcanique importante. Il rappelle que la géodynamique interne est encore active en Afrique.</div><div class='astuce'><b>Astuce :</b> retiens que le foyer est en profondeur et l'épicentre est en surface, juste au-dessus. Les dégâts sont souvent les plus forts près de l'épicentre.</div>",
