    "titre": "Les écosystèmes et la biodiversité",
    "duree": "40 min",
    "contenu": "<p>Un <b>écosystème</b> est l'ensemble formé par un milieu de vie (biotope) et les êtres vivants qui y vivent (biocénose). Les êtres vivants interagissent entre eux et avec leur milieu.</p><div class='definition'><b>Le biotope</b> est le milieu physique : sol, eau, air, climat.<br><b>La biocénose</b> est l'ensemble des êtres vivants : végétaux, animaux, micro-organismes.<br><b>La biodiversité</b> désigne la variété des espèces, des gènes et des écosystèmes sur Terre.<br><b>Une chaîne alimentaire</b> montre qui mange qui : producteur (plante), consommateur (herbivore, carnivore), décomposeur (champignon, bactérie).</div><p>Chaque espèce a un rôle dans l'écosystème. La disparition d'une espèce peut déséquilibrer toute la chaîne alimentaire.</p><div class='exemple'><b>Exemple :</b> dans la forêt camerounaise, les arbres sont des producteurs, les singes et les insectes des consommateurs, et les champignons du sol des décomposeurs. Couper la forêt détruit tout cet équilibre.</div><div class='astuce'><b>Astuce :</b> pour analyser un écosystème, identifie d'abord le biotope (le milieu), puis la biocénose (les êtres vivants), puis les liens entre eux.</div>",
