    "contenu": "<p>La vie scolaire a son vocabulaire propre. Connaître ces mots te permet de parler de ton établissement, de tes cours et de tes activités en anglais.</p><div class='definition'><b>Les matières :</b> maths (mathematics), English, science, history, geography, physics, chemistry, biology, music, physical education (PE).<br><b>Le matériel :</b> a notebook (cahier), a pen (stylo), a pencil (crayon), a ruler (règle), a rubber (gomme), a schoolbag (cartable).<br><b>Les personnes :</b> a pupil ou a student (élève), a teacher (professeur), a headmaster (directeur), a classmate (camarade de classe).<br><b>Les lieux :</b> the classroom (la salle de classe), the library (la bibliothèque), the playground (la cour de récréation), the canteen (la cantine).<br><b>Les expressions :</b> to do homework (faire ses devoirs), to revise for an exam (réviser un examen), to take notes (prendre des notes).</div><div class='exemple'><b>Exemple :</b> <i>My favourite subject is English. I take notes in my notebook, and I do my homework in the library after school.</i></div><div class='astuce'><b>Astuce :</b> retiens les mots par groupes (matières, matériel, lieux). Un bon moyen est de nommer chaque objet de ta salle de classe en anglais.</div>",
