    "titre": "Les institutions internationales et la coopération",
    "duree": "40 min",
    "contenu": "<p>Les États ne peuvent pas toujours résoudre seuls les problèmes qui les dépassent : pauvreté, maladies, changement climatique, conflits. Ils se regroupent alors au sein d'<b>organisations internationales</b>.</p><div class='definition'><b>L'ONU</b> (Organisation des Nations unies, fondée en 1945) réunit la plupart des pays du monde pour maintenir la paix et promouvoir les droits humains.<br><b>L'Union africaine</b> (UA) regroupe les États du continent africain et promeut l'intégration, la paix et le développement.<br><b>L'UNESCO</b> agit pour l'éducation, la science et la culture.<br><b>La coopération internationale</b> désigne l'aide et l'action commune entre États pour atteindre un objectif commun.</div><p>Les organisations internationales ont des missions très variées : santé (OMS), enfance (UNICEF), développement (PNUD), alimentation (FAO).</p><div class='exemple'><b>Exemple :</b> lors d'une épidémie, l'OMS coordonne les actions des pays pour surveiller la maladie, partager les informations et organiser les soins.</div><div class='astuce'><b>Astuce :</b> retiens le domaine de chaque organisation : ONU (paix), Union africaine (Afrique), UNESCO (éducation et culture), OMS (santé), UNICEF (enfance).</div>",
