    "id": "eps4-athletisme-lancer",
    "titre": "L'athlétisme : le lancer de balle (ou de poids)",
    "duree": "40 min",
    "contenu": "<p>Le <b>lancer</b> est une épreuve d'athlétisme qui consiste à projeter un engin le plus loin possible, dans un secteur délimité. On peut lancer une balle, un javelot, un disque ou un poids.</p><div class='definition'><b>L'élan</b> est la phase qui précède le lancer : la prise d'élan permet d'accumuler de l'énergie.<br><b>Le transfert de force</b> est le passage de l'énergie des jambes vers le tronc, puis vers le bras.<br><b>Le lâcher</b> est le moment où l'engin quitte la main, avec un angle favorable (environ 35 à 45 degrés pour un lancer loin).<br><b>La règle de sécurité</b> impose de ne jamais lancer sans vérifier que la zone est libre et de ne pas franchir la ligne.</div><p>Un bon lancer combine force, vitesse et coordination. Les jambes poussent, le tronc se tourne, le bras accompagne le geste.</p><div class='exemple'><b>Exemple :</b> pour lancer une balle, l'élève fait un pas de côté, pivote en tournant les hanches, puis lâche la balle en dirigeant le bras vers l'avant et vers le haut.</div><div class='astuce'><b>Astuce :</b> le mouvement est un enchaînement : jambes, hanches, épaule, bras. Plus la chaîne est fluide, plus le lancer est loin.</div>",
