    "duree": "40 min",
    "contenu": "<p>Pendant une activité sportive, un accident peut arriver. Savoir réagir calmement et correctement peut éviter qu'une blessure devienne grave.</p><div class='definition'><b>Protéger</b> : éviter tout nouveau danger pour soi-même et pour la victime, avant d'intervenir.<br><b>Alerter</b> : prévenir les secours (un adulte, l'enseignant, le centre de santé ou le numéro d'urgence).<br><b>Secourir</b> : apporter les premiers gestes adaptés, sans aggraver la blessure.<br><b>La plaie</b> doit être nettoyée à l'eau propre, puis protégée d'un pansement.<br><b>Une entorse</b> (cheville tordue) nécessite de reposer la zone, de la surélever et de la mettre dans un linge froid, puis de consulter.</div><p>Il ne faut jamais déplacer une personne qui a reçu un coup à la tête ou au dos sans l'avis d'un adulte formé.</p><div class='exemple'><b>Exemple :</b> pendant un match, un élève se tord la cheville. L'enseignant le fait s'arrêter, lui fait poser le pied sur un support, applique une compresse froide et prévient l'infirmerie.</div><div class='astuce'><b>Astuce :</b> retiens la règle PAS : Protéger, Alerter, Secourir. Dans cet ordre, toujours.</div>",
