    "id": "g4-climats-monde",
    "titre": "Les grands climats du monde et leurs zones",
    "duree": "40 min",
    "contenu": "<p>Le <b>climat</b> d'un lieu dépend surtout de sa <b>latitude</b> (distance à l'équateur), de son <b>altitude</b> et de sa position par rapport à la mer. On distingue de grandes zones climatiques sur la Terre.</p><div class='definition'><b>Le climat équatorial</b> est chaud et humide toute l'année (forêts denses, Amazonie, bassin du Congo).<br><b>Le climat tropical</b> alterne une saison sèche et une saison des pluies (savanes du Soudan et du Sahel).<br><b>Le climat désertique</b> est très chaud et très sec, avec des écarts de température importants (Sahara).<br><b>Le climat tempéré</b> connaît des saisons bien marquées (Europe occidentale).<br><b>Le climat polaire</b> est très froid toute l'année (Groenland, Antarctique).</div><p>Plus on s'éloigne de l'équateur, plus les températures baissent : les zones climatiques se répartissent en bandes approximativement parallèles à l'équateur.</p><div class='exemple'><b>Exemple :</b> le Cameroun, proche de l'équateur, connaît un climat équatorial au sud et tropical au centre et au nord. Il est donc varié selon sa latitude et son relief.</div><div class='astuce'><b>Astuce :</b> pour deviner le climat d'un lieu, regarde d'abord sa latitude : plus il est proche de l'équateur, plus il est chaud. Puis considère l'altitude et la proximité de la mer, qui modifient le climat.</div>",
