    "id": "g4-urbanisation-mondiale",
    "titre": "L'urbanisation : villes, croissance et défis",
    "duree": "40 min",
    "contenu": "<p>L'<b>urbanisation</b> est l'augmentation de la part de la population qui vit dans les villes. Aujourd'hui, plus de la moitié de l'humanité habite en ville.</p><div class='definition'><b>Une métropole</b> est une très grande ville qui exerce une influence sur une vaste région.<br><b>La mégalopole</b> est un ensemble de plusieurs métropoles qui se rejoignent.<br><b>La croissance urbaine</b> est l'augmentation de la population des villes, due à l'exode rural et à la natalité.<br><b>Le bidonville</b> est un quartier informel, sans équipements suffisants, où vivent beaucoup de personnes pauvres.</div><p>L'urbanisation rapide pose des défis : logement, eau potable, assainissement, transports, emploi. Les pays en développement, comme ceux d'Afrique, connaissent une croissance urbaine très forte.</p><div class='exemple'><b>Exemple :</b> à Douala ou à Yaoundé, la population a fortement augmenté en quelques décennies. Les quartiers se sont étendus, et l'accès à l'eau et aux transports est devenu un enjeu important.</div><div class='astuce'><b>Astuce :</b> pour parler de l'urbanisation, utilise trois idées : la croissance de la population urbaine, les causes (exode rural, natalité) et les conséquences (défis de logement, d'eau, de transport).</div>",
