    "duree": "40 min",
    "contenu": "<p>Les pays du monde ne sont pas tous au même niveau de développement. On distingue les <b>pays développés</b> (Europe de l'Ouest, Amérique du Nord, Japon) et les <b>pays en développement</b> (Afrique, Asie du Sud, Amérique latine).</p><div class='definition'><b>Le développement</b> désigne l'amélioration des conditions de vie : santé, éducation, revenus, accès à l'eau et à l'énergie.<br><b>L'indicateur de développement humain (IDH)</b> combine espérance de vie, niveau d'éducation et revenu par habitant. Il permet de comparer les pays.<br><b>Les inégalités</b> sont les écarts entre les riches et les pauvres, entre les pays et à l'intérieur d'un même pays.</div><p>Les pays en développement ont souvent une espérance de vie plus faible, un accès à l'éducation plus limité et des revenus moins élevés. Mais ils sont aussi très dynamiques et ont une jeunesse nombreuse.</p><div class='exemple'><b>Exemple :</b> au Cameroun, l'accès à l'eau potable et à l'électricité progresse, mais des écarts importants demeurent entre les villes et les campagnes.</div><div class='astuce'><b>Astuce :</b> ne réduis pas le développement au revenu. La santé et l'éducation comptent autant : un pays peut être riche et inégalitaire, ou moins riche avec une bonne éducation.</div>",
