    "id": "h4-colonisation-berlin",
    "titre": "La colonisation de l'Afrique et la conférence de Berlin",
    "duree": "40 min",
    "contenu": "<p>À la fin du XIXe siècle, les grandes puissances européennes, comme la France, la Grande-Bretagne, l'Allemagne, la Belgique et le Portugal, se partagent l'Afrique. C'est la <b>colonisation</b>.</p><div class='definition'><b>La colonisation</b> est la domination d'un territoire par une puissance étrangère, qui l'administre et exploite ses richesses.<br><b>La conférence de Berlin</b> (1884-1885) réunit les puissances européennes pour se partager le continent africain, sans consulter les peuples africains.<br><b>Le partage</b> a été réalisé en traçant des frontières, souvent artificielles, qui ne tenaient pas compte des peuples et des régions.</div><p>Les colonisateurs ont imposé leur administration, leur langue et leur économie, centrée sur l'exportation de matières premières. Les résistances africaines, comme celles de Samory Touré ou des Ashanti, ont été nombreuses.</p><div class='exemple'><b>Exemple :</b> un même peuple peut se retrouver coupé en deux par une frontière tracée à Berlin, ce qui a créé des problèmes durables après les indépendances.</div><div class='astuce'><b>Astuce :</b> retiens les dates clés : conférence de Berlin (1884-1885), partage de l'Afrique, puis indépendances après la Seconde Guerre mondiale, surtout entre 1957 et 1960.</div>",
