    "duree": "40 min",
    "contenu": "<p>Le Cameroun a connu plusieurs puissances coloniales. Son histoire coloniale est un exemple de la façon dont le continent africain a été partagé et administré.</p><div class='definition'><b>Le Kamerun allemand</b> : en 1884, l'Allemagne établit un protectorat sur le littoral, notamment à Douala, puis étend son contrôle à l'intérieur du pays.<br><b>La tutelle franco-britannique</b> : pendant la Première Guerre mondiale, l'Allemagne est vaincue au Cameroun. Après 1919, la Société des Nations confie le territoire à la France et au Royaume-Uni (mandats).<br><b>Le Cameroun français</b> devient indépendant le 1er janvier 1960. Le Cameroun britannique se réunit au Cameroun francophone en 1961, après un référendum.</div><div class='exemple'><b>Exemple :</b> la ville de Douala, port du littoral, est un centre important dès la période allemande. Elle reste aujourd'hui la capitale économique du pays.</div><div class='astuce'><b>Astuce :</b> retiens la succession : Allemagne (1884), puis France et Royaume-Uni (après 1918), puis indépendance (1960) et réunification (1961).</div>",
