    "id": "i4-reseaux-internet",
    "titre": "Réseaux et internet : client, serveur et adresses IP",
    "duree": "40 min",
    "contenu": "<p>Un <b>réseau informatique</b> relie plusieurs appareils pour qu'ils échangent des informations. Le plus grand réseau du monde est <b>internet</b>, qui relie des millions de réseaux.</p><div class='definition'><b>Un client</b> est un appareil qui demande une information (ton téléphone, ton ordinateur).<br><b>Un serveur</b> est un ordinateur puissant qui fournit des services et des données aux clients (site web, messagerie).<br><b>Une adresse IP</b> est un numéro unique qui identifie un appareil sur le réseau (par exemple 192.168.1.10).<br><b>Un réseau local</b> relie les appareils d'un même lieu (école, maison). <b>Internet</b> relie les réseaux du monde entier.</div><p>Quand tu consultes un site, ton appareil (client) envoie une demande au serveur, qui renvoie la page demandée. Les données voyagent sous forme de petits paquets.</p><div class='exemple'><b>Exemple :</b> dans une salle informatique de ton école, les ordinateurs sont reliés à un serveur qui stocke les fichiers communs. Chaque élève accède aux documents depuis son poste.</div><div class='astuce'><b>Astuce :</b> retiens le schéma : client demande, serveur répond. C'est le principe de presque tous les services en ligne.</div>",
