    "titre": "Les variables et l'affectation dans un algorithme",
    "duree": "40 min",
    "contenu": "<p>Une <b>variable</b> est un espace de la mémoire qui porte un nom et qui contient une valeur. Sa valeur peut changer pendant l'exécution du programme.</p><div class='definition'><b>Une variable</b> se désigne par un nom (par exemple age, score, total).<br><b>L'affectation</b> donne une valeur à une variable. Elle s'écrit avec une flèche : x ← 5, ou en pseudo-code : x = 5.<br><b>Une variable</b> peut changer : si x vaut 5 et qu'on écrit x ← x + 1, alors x vaut 6.<br><b>Le type</b> de la variable indique la nature de la valeur : nombre, texte, booléen (vrai ou faux).</div><div class='exemple'><b>Exemple :</b> algorithme : score ← 0 ; score ← score + 10 ; score ← score + 10 ; afficher score. Le résultat affiché est 20.</div><div class='astuce'><b>Astuce :</b> lis toujours l'affectation de droite à gauche : on calcule d'abord la valeur à droite, puis on la range dans la variable à gauche.</div>",
