    "duree": "40 min",
    "contenu": "<p>Les créations numériques (textes, photos, musiques, logiciels) appartiennent à leurs auteurs. Utiliser une création sans autorisation peut constituer une <b>contrefaçon</b>, qui est punie par la loi.</p><div class='definition'><b>Le droit d'auteur</b> protège la création d'une œuvre. L'auteur décide de son utilisation.<br><b>La contrefaçon</b> est la copie ou l'utilisation non autorisée d'une œuvre protégée.<br><b>Un logiciel libre</b> peut être utilisé, étudié, modifié et redistribué librement, dans le respect de sa licence. Exemple : LibreOffice, Linux.<br><b>Un logiciel propriétaire</b> est soumis à une licence payante ou restrictive. Son usage est limité.<br><b>La citation</b> d'une source doit toujours mentionner l'auteur et le document d'origine.</div><div class='exemple'><b>Exemple :</b> pour un exposé, tu copies une photo trouvée sur internet sans indiquer son auteur. Tu risques une contrefaçon. Il faut citer la source ou utiliser une image libre de droits.</div><div class='astuce'><b>Astuce :</b> avant d'utiliser une image ou un texte trouvé en ligne, cherche la mention de la licence. En cas de doute, demande l'autorisation ou choisis une ressource libre.</div>",
