    "titre": "Les équations du premier degré",
    "duree": "40 min",
    "contenu": "<p>Une <b>équation</b> est une égalité qui contient une inconnue (souvent notée x). Résoudre l'équation, c'est trouver la valeur de x qui rend l'égalité vraie.</p><div class='definition'><b>Règles de résolution :</b><br>1) on peut ajouter ou soustraire le même nombre aux deux membres ;<br>2) on peut multiplier ou diviser les deux membres par le même nombre non nul.<br><b>Vérifier</b> une solution : on remplace x par la valeur trouvée et on contrôle que l'égalité est vraie.</div><div class='exemple'><b>Exemple :</b> résoudre 2x + 3 = 11. On soustrait 3 : 2x = 8. On divise par 2 : x = 4. Vérification : 2 × 4 + 3 = 11 ✓.</div><p><b>Problème :</b> au marché, 3 mangues et 2 ananas coûtent 1 600 FCFA ; une mangue coûte 300 FCFA. Quel est le prix d'un ananas ? On écrit 3 × 300 + 2p = 1 600, donc 2p = 700, soit p = 350 FCFA.</p><div class='astuce'><b>Astuce :</b> pour résoudre une équation, regroupe les x d'un côté et les nombres de l'autre, puis divise. Termine toujours par une vérification.</div>",
