    "titre": "Atomes, éléments et molécules",
    "duree": "40 min",
    "contenu": "<p>Toute la matière est constituée d'<b>atomes</b>. Un atome est la plus petite partie d'un élément chimique qui garde les propriétés de cet élément.</p><div class='definition'><b>Un élément chimique</b> est une sorte d'atome caractérisée par son symbole : H (hydrogène), O (oxygène), C (carbone), Fe (fer), Na (sodium).<br><b>Une molécule</b> est un assemblage d'atomes liés entre eux. Ex. : la molécule d'eau est H2O (2 atomes d'hydrogène et 1 atome d'oxygène).<br><b>Un corps pur simple</b> est formé d'un seul élément (O2, Fe). <b>Un corps pur composé</b> est formé de plusieurs éléments (H2O, CO2).<br><b>La formule chimique</b> indique la nature et le nombre d'atomes d'une molécule.</div><div class='exemple'><b>Exemple :</b> le dioxyde de carbone CO2 contient 1 atome de carbone (C) et 2 atomes d'oxygène (O). C'est un corps pur composé.</div><div class='astuce'><b>Astuce :</b> dans une formule, le petit chiffre indique le nombre d'atomes de l'élément qui le précède. Sans chiffre, il n'y a qu'un atome. Ainsi, H2O contient 2 H et 1 O.</div>",
