    "duree": "40 min",
    "contenu": "<p>La <b>reproduction humaine</b> permet la formation d'un nouvel être. Elle repose sur la rencontre d'un <b>spermatozoïde</b> (cellule reproductrice masculine) et d'un <b>ovule</b> (cellule reproductrice féminine).</p><div class='definition'><b>La puberté</b> est la période où le corps devient capable de se reproduire. Elle s'accompagne de changements physiques et hormonaux.<br><b>Chez le garçon</b> : apparition de la barbe et de la pomme d'Adam, élargissement des épaules, mue de la voix, production de spermatozoïdes.<br><b>Chez la fille</b> : développement des seins, apparition des règles (menstruations), élargissement du bassin.<br><b>La fécondation</b> est la rencontre de l'ovule et du spermatozoïde, qui a généralement lieu dans la trompe de Fallope.</div><div class='exemple'><b>Exemple :</b> lors de la puberté, un élève de 13 ans voit sa voix changer. C'est une conséquence de l'action des hormones sur le larynx.</div><div class='astuce'><b>Astuce :</b> la puberté ne se produit pas au même âge chez tout le monde. Il est normal d'avoir des différences de rythme entre camarades. Parle-en à un adulte de confiance si tu as des questions.</div>",
