    "titre": "Les IST et le VIH/SIDA : prévention et comportements responsables",
    "duree": "40 min",
    "contenu": "<p>Les <b>infections sexuellement transmissibles (IST)</b> sont des maladies transmises lors de rapports sexuels non protégés. Certaines sont bénignes, d'autres peuvent avoir des conséquences graves sur la santé.</p><div class='definition'><b>Le VIH</b> (virus de l'immunodéficience humaine) attaque les défenses immunitaires de l'organisme.<br><b>Le SIDA</b> (syndrome d'immunodéficience acquise) est le stade avancé de l'infection par le VIH, où le corps ne peut plus se défendre contre les infections.<br><b>La transmission</b> du VIH se fait par le sang, les rapports sexuels non protégés et de la mère à l'enfant.<br><b>La prévention</b> consiste à utiliser un préservatif, à se faire dépister, à éviter de partager des objets qui peuvent contenir du sang (lames, aiguilles).</div><p>Le VIH ne se transmet pas par la salive, la poignée de main, le partage d'un repas ou l'air.</p><div class='exemple'><b>Exemple :</b> un jeune qui partage une lame de rasoir avec un ami peut transmettre le virus si la lame contient du sang. Ne jamais partager ce type d'objet.</div><div class='astuce'><b>Astuce :</b> le seul moyen de savoir si l'on est infecté est de se faire dépister. Un test rapide et gratuit existe dans de nombreux centres de santé au Cameroun.</div>",
