    "id": "s4-formation-sol",
    "titre": "Le sol : formation, composition et érosion",
    "duree": "40 min",
    "contenu": "<p>Le <b>sol</b> est la couche superficielle de la croûte terrestre. Il est indispensable à la vie : il fournit de l'eau, des sels minéraux et un support aux plantes.</p><div class='definition'><b>L'altération</b> est la dégradation des roches sous l'effet de l'eau, du vent, du gel et des variations de température.<br><b>L'humus</b> est la matière organique issue de la décomposition des êtres vivants (feuilles, animaux morts).<br><b>La texture du sol</b> dépend de la taille des particules : sable (grosses), limon (moyennes), argile (très fines).<br><b>L'érosion</b> est l'usure et le transport du sol par l'eau ou le vent.</div><p>Un sol fertile contient de l'humus, de l'eau et des sels minéraux. Les vers de terre et les micro-organismes participent à sa formation.</p><div class='exemple'><b>Exemple :</b> au Cameroun, lorsque la forêt est coupée sur une pente, les pluies emportent la couche de terre fertile : c'est l'érosion. Le sol devient pauvre et ne peut plus être cultivé.</div><div class='astuce'><b>Astuce :</b> pour protéger le sol, garde-le couvert de végétation, évite les feux de brousse et les cultures sur de fortes pentes sans aménagement.</div>",
