    "duree": "40 min",
    "contenu": "<p>Beaucoup de verbes très courants sont <b>irréguliers</b> : leur forme au passé ne suit pas la règle du -ed. Il faut les apprendre par cœur.</p><div class='definition'><b>Verbes irréguliers courants :</b><br>go → went (aller) · see → saw (voir) · have → had (avoir) · eat → ate (manger) · drink → drank (boire) · write → wrote (écrire) · make → made (faire, fabriquer) · take → took (prendre) · come → came (venir) · do → did (faire) · buy → bought (acheter) · give → gave (donner).</div><div class='exemple'><b>Exemple :</b> <i>Last Monday, I went to the market. I bought fresh fish and I ate lunch with my family.</i> (Lundi dernier, je suis allé au marché. J'ai acheté du poisson frais et j'ai mangé avec ma famille.)</div><div class='astuce'><b>Astuce :</b> regroupe les verbes irréguliers par sons. Ex. : see → saw, make → made... Mais le plus efficace reste de répéter la liste à voix haute pendant 5 minutes par jour.</div>",
