    "titre": "Comparer : comparatives et superlatives",
    "duree": "40 min",
    "contenu": "<p>Pour comparer deux personnes ou deux choses, on utilise le <b>comparatif</b>. Pour désigner le plus haut degré, on utilise le <b>superlatif</b>.</p><div class='definition'><b>Adjectif court</b> (une syllabe) : comparatif = adjectif + -er + than ; superlatif = the + adjectif + -est. Ex. : tall → taller than ; the tallest.<br><b>Adjectif long</b> (deux syllabes ou plus) : comparatif = more + adjectif + than ; superlatif = the most + adjectif. Ex. : beautiful → more beautiful than ; the most beautiful.<br><b>Adjectifs irréguliers :</b> good → better ; bad → worse.</div><div class='exemple'><b>Exemple :</b> <i>Douala is bigger than Bafoussam. Yaoundé is the most beautiful city in my opinion.</i> (Douala est plus grande que Bafoussam.)</div><div class='astuce'><b>Astuce :</b> pour un adjectif court qui finit par -y, change y en -ier : happy → happier ; the happiest.</div>",
