    "titre": "Les institutions de l'État camerounais",
    "duree": "40 min",
    "contenu": "<p>Un État fonctionne grâce à des <b>institutions</b> qui exercent le pouvoir. On distingue généralement trois pouvoirs, qui doivent être séparés pour éviter l'abus de pouvoir : le <b>pouvoir exécutif</b>, le <b>pouvoir législatif</b> et le <b>pouvoir judiciaire</b>.</p><div class='definition'><b>Le pouvoir exécutif</b> applique les lois et gère l'État. Au Cameroun, il est exercé par le Président de la République, assisté du Gouvernement.<br><b>Le pouvoir législatif</b> vote les lois. Il est exercé par le Parlement, composé de l'Assemblée nationale et du Sénat.<br><b>Le pouvoir judiciaire</b> rend la justice et veille au respect des lois. Il est exercé par les tribunaux.</div><p>La <b>séparation des pouvoirs</b> est un principe démocratique : aucun de ces pouvoirs ne doit dominer les autres.</p><div class='exemple'><b>Exemple :</b> lorsqu'un juge tranche un litige entre deux personnes, il exerce le pouvoir judiciaire. Lorsque les députés votent une nouvelle loi sur l'école, ils exercent le pouvoir législatif.</div><div class='astuce'><b>Astuce :</b> retiens les trois pouvoirs avec le verbe qui les caractérise : exécuter (exécutif), voter la loi (législatif), juger (judiciaire).</div>",
