    "titre": "Protéger l'environnement : un devoir citoyen",
    "duree": "40 min",
    "contenu": "<p>L'<b>environnement</b> désigne l'ensemble des éléments naturels (air, eau, sol, forêts, animaux) et des aménagements humains. Le protéger est une responsabilité de tous les citoyens.</p><div class='definition'><b>La pollution</b> est la dégradation de l'environnement par des substances nocives : déchets plastiques, fumées, eaux usées.<br><b>Le développement durable</b> consiste à répondre aux besoins actuels sans compromettre la capacité des générations futures à répondre aux leurs.<br><b>Le recyclage</b> consiste à transformer les déchets pour les réutiliser.</div><p>Au Cameroun, la déforestation, la pollution des cours d'eau par les déchets et l'érosion des sols sont des problèmes importants. Chacun peut agir : trier ses déchets, ne pas jeter de plastique dans la nature, planter des arbres.</p><div class='exemple'><b>Exemple :</b> à Douala, des sachets plastiques bouchent les caniveaux et polluent le fleuve. Ramasser les déchets et les mettre dans une poubelle est un geste citoyen.</div><div class='astuce'><b>Astuce :</b> pense à la règle des 3R : réduire, réutiliser, recycler. C'est la base d'une attitude écologique.</div>",
