    "duree": "40 min",
    "contenu": "<p>La <b>condition physique</b> regroupe les qualités qui permettent de pratiquer une activité sportive sans se fatiguer trop vite et sans risque. Elle se développe par un entraînement régulier.</p><div class='definition'><b>L'endurance</b> est la capacité à maintenir un effort long, à intensité modérée.<br><b>La force</b> est la capacité à produire un effort important contre une résistance (soulever, pousser, sauter).<br><b>La souplesse</b> est la capacité des articulations à effectuer une grande amplitude de mouvement.<br><b>La vitesse</b> est la capacité à effectuer un déplacement ou un geste rapidement.</div><p>Pour progresser, il faut un entraînement <b>régulier</b>, <b>progressif</b> (on augmente la charge petit à petit) et <b>varié</b> (on travaille plusieurs qualités).</p><div class='exemple'><b>Exemple :</b> pour améliorer l'endurance, on court 15 minutes à allure modérée trois fois par semaine. Pour la souplesse, on fait des étirements doux après chaque séance.</div><div class='astuce'><b>Astuce :</b> augmente la difficulté de 10 % à la fois, pas plus. Un progrès trop rapide provoque souvent des douleurs ou des blessures.</div>",
