    "duree": "40 min",
    "contenu": "<p>Le <b>saut en longueur</b> est une épreuve d'athlétisme qui consiste à sauter le plus loin possible à partir d'une planche d'appel. Il combine vitesse, impulsion et coordination.</p><div class='definition'><b>La course d'élan</b> est la phase de course qui prépare le saut. Elle doit être progressive et régulière.<br><b>La planche d'appel</b> est la zone à partir de laquelle on s'élance. On ne doit pas la dépasser : c'est une faute.<br><b>L'impulsion</b> est la poussée puissante du pied d'appel qui projette le corps vers l'avant.<br><b>La réception</b> consiste à atterrir le plus loin possible, les jambes en avant, sans reculer les fesses.</div><p>La mesure se fait à partir du bord de la planche jusqu'à la trace la plus proche laissée par le corps dans le sable.</p><div class='exemple'><b>Exemple :</b> un élève qui court, pose le pied sur la planche, pousse fort puis atterrit les jambes tendues dans le sable réalise un saut bien exécuté.</div><div class='astuce'><b>Astuce :</b> pendant le vol, lève les genoux vers la poitrine et bras vers l'avant : cela prolonge le saut. Pour la réception, ramène les jambes vers l'avant.</div>",
