    "titre": "Le handball : passes, tirs et règles de base",
    "duree": "40 min",
    "contenu": "<p>Le <b>handball</b> est un sport collectif joué à sept contre sept, avec un ballon que l'on peut tenir, passer et lancer avec les mains. L'objectif est de marquer des buts dans la cage adverse.</p><div class='definition'><b>La passe</b> est l'envoi du ballon à un coéquipier. On la réalise à deux mains ou à une main.<br><b>Le tir</b> est le lancer du ballon vers le but.<br><b>Le dribble</b> est le fait de faire rebondir le ballon sur le sol en se déplaçant.<br><b>Le pas</b> : un joueur ne peut pas faire plus de trois pas en tenant le ballon sans le lâcher ou le passer.<br><b>Le marquage</b> consiste à surveiller un adversaire pour l'empêcher de recevoir le ballon.</div><p>Les règles essentielles interdisent de toucher le ballon avec les pieds (sauf le gardien dans sa surface), de frapper un adversaire et de bloquer un adversaire sans ballon.</p><div class='exemple'><b>Exemple :</b> un joueur reçoit le ballon, fait une passe à son coéquipier démarqué, qui tire au but. Il s'agit d'une action collective réussie.</div><div class='astuce'><b>Astuce :</b> pour bien passer, regarde ton coéquipier et non le ballon. Le démarquage (se libérer du marquage) est souvent plus efficace qu'un long dribble.</div>",
