    "contenu": "<p><b>Course de vitesse :</b> épreuve où l'on court une distance courte (souvent 60 m ou 100 m) le plus vite possible.</p>\n<p><b>Les phases de la course :</b> le départ (position basse, poussée des bras et des jambes), l'accélération (on relève progressivement le buste), la course à vitesse maximale, et l'arrivée (on court jusqu'à la ligne, sans ralentir avant).</p>\n<p><b>Conseil :</b> un bon échauffement avant la course réduit le risque de blessure, surtout dans les muscles des jambes.</p>\n<p><b>Exemple :</b> lors d'une course de 60 m à l'école, l'élève part en position basse, accélère, puis court jusqu'à la ligne sans s'arrêter avant l'arrivée.</p>",
