    "duree": "40 min",
    "contenu": "<p>L'<b>Afrique</b> est le deuxième continent du monde par sa superficie. Elle est traversée par l'équateur et la plupart de ses terres se situent entre les deux tropiques.</p><div class='definition'><b>Le relief africain</b> est formé de vastes plateaux et de bassins, séparés par quelques grandes chaînes de montagnes.<br><b>Les plateaux</b> dominent largement le continent : on parle de « continent de plateaux ».<br><b>Les grands fleuves</b> : le Nil, le Congo, le Niger, le Zambèze.<br><b>Le Sahara</b> est le plus grand désert chaud du monde.</div><p>L'Afrique possède aussi de hautes montagnes, comme le Kilimandjaro (en Tanzanie), et le Rift, une grande fracture de l'écorce terrestre qui traverse l'Afrique de l'Est.</p><div class='exemple'><b>Exemple :</b> le bassin du Congo, au centre de l'Afrique, est une vaste cuvette recouverte d'une forêt équatoriale très dense. Le fleuve Congo y draine une grande partie de la région.</div><div class='astuce'><b>Astuce :</b> pour retenir les grands ensembles, pense à « plateaux au centre et au sud, déserts au nord, montagnes à l'est » : ce sont les grandes lignes du relief africain.</div>",
