    "titre": "Le Cameroun : population, villes et migrations",
    "duree": "40 min",
    "contenu": "<p>Le <b>Cameroun</b> compte plus de 25 millions d'habitants. Sa population est jeune : une grande part a moins de 25 ans. Elle est très diversifiée, avec plus de 250 groupes ethniques et deux langues officielles, le français et l'anglais.</p><div class='definition'><b>La densité de population</b> est le nombre d'habitants par km². Elle est très forte dans certaines régions et faible dans d'autres.<br><b>L'exode rural</b> est le départ des habitants des campagnes vers les villes, à la recherche de travail et de services.<br><b>La croissance urbaine</b> est l'augmentation de la population des villes.</div><p>Les grandes villes sont Douala (port et capitale économique), Yaoundé (capitale politique) et Garoua, Bafoussam ou Bamenda. Elles concentrent les activités économiques, les écoles et les hôpitaux.</p><div class='exemple'><b>Exemple :</b> de nombreux jeunes quittent les villages du Nord pour travailler à Douala ou à Yaoundé. C'est un exemple d'exode rural.</div><div class='astuce'><b>Astuce :</b> pour parler de la population, utilise les trois notions : densité (combien par km²), exode rural (campagne vers ville) et croissance urbaine (ville qui grandit).</div>",
