    "id": "g5-cameroun-agriculture",
    "titre": "L'agriculture et les ressources du Cameroun",
    "duree": "40 min",
    "contenu": "<p>L'<b>agriculture</b> occupe une part importante de la population camerounaise. Elle fournit la nourriture, des matières premières pour l'industrie et des produits d'exportation.</p><div class='definition'><b>Une culture de rente</b> est destinée à la vente à l'étranger : cacao, café, banane, coton, caoutchouc.<br><b>Une culture vivrière</b> sert à nourrir la population : manioc, maïs, igname, plantain, arachide.<br><b>Une ressource naturelle</b> est un élément de la nature utilisé par l'homme : bois, pétrole, eau, minerais.</div><p>Le Cameroun est un pays de forêts au sud, de savanes au centre et au nord. Le sud est favorable aux cultures de rente comme le cacao et la banane. Le nord, plus sec, se prête aux céréales comme le mil et le sorgho.</p><div class='exemple'><b>Exemple :</b> la région du Sud-Ouest produit de la banane et du cacao, tandis que le Nord cultive le coton et le mil.</div><div class='astuce'><b>Astuce :</b> pour distinguer rente et vivrière, demande-toi : la culture est-elle vendue à l'étranger (rente) ou consommée sur place (vivrière) ?</div>",
