    "contenu": "<p><b>Afrique centrale :</b> région du continent africain qui regroupe notamment le Cameroun, le Gabon, le Congo, la RDC, la Centrafrique, le Tchad et la Guinée équatoriale.</p>\n<p><b>Le Cameroun dans sa région :</b> il est l'un des pays les plus variés de la région, avec la forêt au sud, la savane au centre et au nord, et des montagnes à l'ouest.</p>\n<p><b>Ressources :</b> la forêt fournit du bois, le sol permet les cultures comme le cacao et le café, et le sous-sol contient du pétrole.</p>\n<p><b>Exemple :</b> le Cameroun a une façade maritime sur le golfe de Guinée, ce qui facilite les échanges avec les pays voisins comme le Tchad, qui n'a pas d'accès à la mer.</p>",
