    "duree": "40 min",
    "contenu": "<p>La Grèce antique est constituée de nombreuses <b>cités-États</b> indépendantes, dont la plus célèbre est <b>Athènes</b>. C'est à Athènes, vers le Ve siècle avant notre ère, que naît la <b>démocratie</b>.</p><div class='definition'><b>Démocratie :</b> du grec demos (peuple) et kratos (pouvoir). C'est un régime où le peuple exerce le pouvoir.<br><b>L'Assemblée (Ecclésia) :</b> réunion des citoyens qui votent les lois et décident de la guerre et de la paix.<br><b>Le citoyen :</b> à Athènes, seuls les hommes adultes nés de parents athéniens sont citoyens. Les femmes, les esclaves et les étrangers n'ont pas le droit de vote.</div><p>Les Athéniens tirent au sort certaines fonctions pour éviter qu'une seule famille prenne le pouvoir. Périclès, au Ve siècle avant notre ère, est le dirigeant le plus célèbre de cette période.</p><div class='exemple'><b>Exemple :</b> lorsque l'Assemblée décide de construire une flotte de navires, chaque citoyen peut donner son avis et voter. C'est le principe de la démocratie directe.</div><div class='astuce'><b>Astuce :</b> retiens que la démocratie athénienne était réservée à une minorité de la population. C'est un point important à citer dans une dissertation d'histoire.</div>",
