    "duree": "40 min",
    "contenu": "<p>Rome est d'abord une <b>république</b> (509 av. J.-C.), gouvernée par un <b>Sénat</b> et des magistrats élus. En 27 avant notre ère, Auguste devient le premier <b>empereur</b> : c'est le début de l'Empire romain.</p><div class='definition'><b>Empire :</b> territoire très vaste dirigé par un empereur, qui regroupe des peuples différents.<br><b>Romanisation :</b> processus par lequel les peuples conquis adoptent la langue latine, les lois, les coutumes et le mode de vie romains.<br><b>Les voies romaines :</b> routes pavées qui relient les villes de l'Empire et facilitent le commerce et l'armée.</div><p>L'Empire romain s'étend autour de la Méditerranée. Il laisse un héritage important : le droit (lois écrites), la langue latine (à l'origine des langues romanes comme le français, l'espagnol ou l'italien) et l'architecture (arcs, aqueducs, théâtres).</p><div class='exemple'><b>Exemple :</b> le mot « français » vient du latin. Les lois romaines inspirent encore les codes juridiques de nombreux pays d'aujourd'hui.</div><div class='astuce'><b>Astuce :</b> pour retenir les étapes, pense à : République (509 av. J.-C.) → Empire (27 av. J.-C.). Ce passage est au cœur du programme.</div>",
