    "duree": "40 min",
    "contenu": "<p>Le <b>Ghana</b> (ou Wagadou) est un grand empire d'Afrique de l'Ouest, situé entre le Sahara et la savane, vers le VIIIe siècle de notre ère. Il ne doit pas être confondu avec le Ghana actuel, qui porte le même nom.</p><div class='definition'><b>Le commerce transsaharien :</b> échanges entre l'Afrique subsaharienne et l'Afrique du Nord à travers le désert du Sahara.<br><b>Le roi (kaya-magan) :</b> chef de l'empire, qui contrôle le commerce et lève des impôts.<br><b>Les produits d'échange :</b> l'or et les esclaves venaient du sud ; le sel et les produits du Nord arrivaient par les caravanes.</div><p>Le Ghana était très riche grâce à l'or. Il contrôlait les routes du commerce entre le Sud, riche en or, et le Nord, qui avait besoin de l'or. Sa capitale, Koumbi Saleh, était une ville importante.</p><div class='exemple'><b>Exemple :</b> les caravanes transportaient du sel du Sahara vers le sud, où il était très recherché. En échange, elles revenaient avec de l'or.</div><div class='astuce'><b>Astuce :</b> retiens le rôle clé : le Ghana était riche parce qu'il contrôlait le commerce de l'or et du sel entre le Sud et le Nord.</div>",
