    "contenu": "<p>L'<b>empire du Mali</b> succède au Ghana. Il est fondé au XIIIe siècle par <b>Soundiata Keïta</b>, un chef des Malinkés. Son pouvoir s'étend sur une grande partie de l'Afrique de l'Ouest.</p><div class='definition'><b>Soundiata Keïta :</b> fondateur de l'empire du Mali, vainqueur du roi Soumaoro Kanté à la bataille de Kirina (vers 1235).<br><b>La Charte du Mandé :</b> texte de règles transmis oralement, qui organise la vie de l'empire et protège les droits des habitants.<br><b>Mansa Moussa :</b> souverain célèbre du Mali, connu pour son pèlerinage à La Mecque en 1324, qui impressionna le monde par sa richesse.</div><p>L'empire du Mali contrôle le commerce de l'or et du sel. Des villes comme Tombouctou et Djenné deviennent des centres de savoir : écoles coraniques, manuscrits et mosquées.</p><div class='exemple'><b>Exemple :</b> Mansa Moussa, lors de son pèlerinage à La Mecque, distribue tant d'or au Caire que le cours de l'or baisse dans la région.</div><div class='astuce'><b>Astuce :</b> retiens : Ghana (VIIIe s.) → Mali (XIIIe s.), avec Soundiata Keïta comme fondateur et Mansa Moussa comme souverain le plus célèbre.</div>",
