    "id": "i5-traitement-texte",
    "titre": "Le traitement de texte : mise en forme d'un document",
    "duree": "40 min",
    "contenu": "<p>Un <b>traitement de texte</b> permet de saisir, corriger et mettre en forme un document : lettre, rapport, affiche. Une bonne mise en forme rend le texte plus lisible et plus professionnel.</p><div class='definition'><b>La police</b> est le style des caractères (Arial, Times New Roman).<br><b>La taille</b> est la hauteur des caractères, mesurée en points.<br><b>Le gras, l'italique et le souligné</b> sont des styles qui mettent en valeur un mot ou une phrase.<br><b>L'alignement</b> définit la position du texte : à gauche, centré, à droite ou justifié.<br><b>Le titre</b> est un texte plus grand et mis en évidence, qui structure le document.</div><p>Pour bien mettre en forme : utilise peu de polices (deux au maximum), garde une taille de texte uniforme pour le corps du texte et réserve le gras aux titres ou aux mots importants.</p><div class='exemple'><b>Exemple :</b> pour une lettre à ton directeur, utilise un titre centré en gras, un corps de texte justifié en taille 12, et un espace entre chaque paragraphe.</div><div class='astuce'><b>Astuce :</b> l'outil « Reproduire la mise en forme » (pinceau) permet de copier le style d'un texte vers un autre, ce qui fait gagner du temps.</div>",
