    "titre": "Les triangles : somme des angles et triangles particuliers",
    "duree": "40 min",
    "contenu": "<p>Un <b>triangle</b> est une figure à trois côtés et trois angles. Ses trois sommets sont désignés par des lettres, par exemple le triangle ABC.</p><div class='definition'><b>Propriété fondamentale :</b> dans un triangle, la somme des trois angles est égale à <b>180°</b>.<br><b>Triangle isocèle :</b> il a deux côtés de même longueur.<br><b>Triangle équilatéral :</b> il a trois côtés de même longueur et trois angles de 60°.<br><b>Triangle rectangle :</b> il a un angle droit (90°).</div><div class='exemple'><b>Exemple :</b> dans un triangle ABC, si l'angle A mesure 50° et l'angle B mesure 60°, alors l'angle C mesure 180 − 50 − 60 = 70°.</div><p>Un triangle peut avoir plusieurs caractéristiques à la fois : par exemple, un triangle rectangle isocèle a un angle droit et deux côtés égaux.</p><div class='astuce'><b>Astuce :</b> pour trouver un angle manquant, fais « 180 − somme des deux angles connus ». C'est le calcul le plus utilisé en géométrie du collège.</div>",
