    "titre": "La lumière : sources, propagation et ombres",
    "duree": "40 min",
    "contenu": "<p>La <b>lumière</b> permet de voir les objets. Il existe des sources de lumière qui en produisent elles-mêmes, et des objets qui la renvoient seulement.</p><div class='definition'><b>Une source primaire</b> produit sa propre lumière : le Soleil, une lampe, une flamme.<br><b>Une source secondaire</b> renvoie la lumière qu'elle reçoit : la Lune, un miroir, une feuille de papier.<br><b>Propagation rectiligne :</b> dans un milieu homogène et transparent, la lumière se déplace en ligne droite.<br><b>Vitesse de la lumière :</b> environ 300 000 km/s dans le vide ou dans l'air.</div><p>Un objet opaque arrête la lumière et crée une <b>ombre</b> derrière lui. Un objet transparent laisse passer la lumière. Un objet translucide la laisse passer en la diffusant.</p><div class='exemple'><b>Exemple :</b> pendant une éclipse de Lune, la Terre se place entre le Soleil et la Lune : son ombre tombe sur la Lune.</div><div class='astuce'><b>Astuce :</b> pour te rappeler la propagation rectiligne, pense à un rayon de soleil qui passe par une fente : il trace une ligne droite dans la poussière.</div>",
