    "id": "pc5-masse-volumique",
    "titre": "La masse volumique",
    "duree": "40 min",
    "contenu": "<p>Deux objets de même volume n'ont pas forcément la même masse. Pour comparer la « lourdeur » de deux matières à volume égal, on utilise la <b>masse volumique</b>.</p><div class='definition'><b>La masse volumique</b> ρ est la masse d'une unité de volume d'une substance : ρ = m ÷ V.<br>Unités courantes : g/cm³ ou kg/m³ (1 g/cm³ = 1 000 kg/m³).<br><b>Un corps qui a une masse volumique plus grande que l'eau</b> coule. Un corps moins dense que l'eau flotte.</div><div class='exemple'><b>Exemple :</b> 1 cm³ de fer a une masse d'environ 7,9 g : sa masse volumique est 7,9 g/cm³. L'eau a une masse volumique de 1 g/cm³, donc le fer coule dans l'eau.</div><p>Pour calculer la masse à partir de la masse volumique : m = ρ × V. Pour calculer le volume : V = m ÷ ρ.</p><div class='astuce'><b>Astuce :</b> retiens la formule avec le triangle : m en haut, ρ et V en bas (ρ × V = m ; m ÷ V = ρ ; m ÷ ρ = V).</div>",
