    "contenu": "<p><b>Mélange homogène :</b> mélange dont on ne distingue qu'une seule phase à l'œil nu. Exemple : de l'eau sucrée, de l'eau salée.</p>\n<p><b>Mélange hétérogène :</b> mélange dont on distingue plusieurs parties à l'œil nu. Exemple : du sable dans l'eau, de l'huile et de l'eau.</p>\n<p><b>Remarque :</b> un mélange peut sembler homogène et ne pas l'être. Pour le savoir, il faut bien observer, parfois avec une loupe ou un microscope.</p>\n<p><b>Exemple camerounais :</b> le jus de bissap bien filtré est homogène. L'eau de pluie boueuse qui coule dans une rigole est hétérogène.</p>",
