    "titre": "La cellule, unité de base du vivant",
    "duree": "40 min",
    "contenu": "<p>Tous les êtres vivants sont constitués de <b>cellules</b>. La cellule est la plus petite unité vivante : elle peut respirer, se nourrir et se reproduire.</p><div class='definition'><b>La cellule</b> est délimitée par une membrane. Elle contient un <b>noyau</b>, qui renferme l'information génétique, et un <b>cytoplasme</b>, où se déroulent les réactions de la vie.<br><b>Un organisme unicellulaire</b> est formé d'une seule cellule (bactérie, levure).<br><b>Un organisme pluricellulaire</b> est formé de milliards de cellules spécialisées (l'homme, la plante).</div><p>Les cellules végétales possèdent en plus une <b>paroi</b> rigide en cellulose et des <b>chloroplastes</b>, qui contiennent la chlorophylle et permettent la photosynthèse. La cellule animale n'a ni paroi ni chloroplastes.</p><div class='exemple'><b>Exemple :</b> la levure utilisée pour faire le pain est un organisme unicellulaire. Un arbre est pluricellulaire : il est formé de cellules spécialisées, comme celles des racines ou des feuilles.</div><div class='astuce'><b>Astuce :</b> retiens les trois éléments communs à toutes les cellules : la membrane, le cytoplasme et le noyau. La paroi et les chloroplastes sont propres aux cellules végétales.</div>",
