    "titre": "La digestion et l'appareil digestif",
    "duree": "40 min",
    "contenu": "<p>La <b>digestion</b> transforme les aliments en substances assez petites pour être absorbées et utilisées par le corps.</p><div class='definition'><b>La digestion mécanique</b> découpe et écrase les aliments : dents, estomac.<br><b>La digestion chimique</b> les transforme grâce aux sucs digestifs : salive, suc gastrique, bile, suc pancréatique.<br><b>L'absorption</b> fait passer les nutriments dans le sang, principalement dans l'intestin grêle.<br><b>L'élimination</b> évacue les déchets par le gros intestin et l'anus.</div><p>Le trajet des aliments : bouche → pharynx → œsophage → estomac → intestin grêle → gros intestin → anus.</p><div class='exemple'><b>Exemple :</b> la salive contient une enzyme qui commence à transformer l'amidon du manioc en sucres simples dès la bouche.</div><div class='astuce'><b>Astuce :</b> pour retenir le trajet, pense à une phrase : « Beaux Pains Œufs Estomac Grêle Gros Anus ». Chaque mot correspond à une étape du tube digestif.</div>",
