    "id": "a6-greetings-to-be",
    "titre": "Greetings and the verb « to be »",
    "duree": "40 min",
    "contenu": "<p>En anglais, on se salue et on se présente avec le verbe <b>to be</b> (être). C'est le verbe le plus important du début de l'année.</p><div class='definition'><b>To be au présent :</b><br>I am (je suis) · you are (tu es / vous êtes) · he is (il est) · she is (elle est) · it is (il/elle est, pour une chose ou un animal) · we are (nous sommes) · they are (ils/elles sont).</div><div class='exemple'><b>Exemple :</b> <i>Hello! I am Awa. I am from Douala. We are in class 6.</i> (Bonjour ! Je suis Awa. Je viens de Douala. Nous sommes en 6ème.)</div><p>Les <b>formes contractées</b> sont très utilisées à l'oral et à l'écrit : I am → <b>I'm</b>, he is → <b>he's</b>, we are → <b>we're</b>, they are → <b>they're</b>.</p><p>À la forme négative, on ajoute <b>not</b> après le verbe : I am not = I'm not ; he is not = he isn't.</p><p>Pour poser une question, on inverse le verbe et le sujet : <i>Are you ready?</i> (Tu es prêt ?)</p><div class='astuce'><b>Astuce :</b> les formules pour se saluer : <i>Good morning</i> (le matin), <i>Good afternoon</i> (l'après-midi), <i>Good evening</i> (le soir), et <i>Good night</i> pour dire bonne nuit.</div>",
