    "id": "a6-family-possessives",
    "titre": "My family : possessive adjectives",
    "duree": "40 min",
    "contenu": "<p>Pour parler de sa famille, on utilise des <b>adjectifs possessifs</b>. En anglais, ils s'accordent avec la personne qui possède, et non avec l'objet possédé.</p><div class='definition'><b>Adjectifs possessifs :</b><br>my (mon, ma, mes) · your (ton, ta, tes / votre) · his (son, sa, ses — pour un homme) · her (son, sa, ses — pour une femme) · its (son, sa, ses — pour un animal ou une chose) · our (notre, nos) · their (leur, leurs).</div><div class='exemple'><b>Exemple :</b> <i>This is my father. His name is Jean. Her name is Marie, she is my mother.</i> (C'est mon père. Son nom est Jean. Son nom est Marie, c'est ma mère.)</div><p><b>Vocabulaire de la famille :</b> father (père), mother (mère), brother (frère), sister (sœur), grandfather (grand-père), grandmother (grand-mère), cousin (cousin/cousine), uncle (oncle), aunt (tante).</p><div class='astuce'><b>Astuce :</b> en anglais, on ne dit pas « son » ou « sa » selon l'objet. On dit <i>his</i> ou <i>her</i> selon le sexe de la personne qui possède. Ex. : <i>his book</i> (son livre à lui), <i>her book</i> (son livre à elle).</div>",
