    "duree": "40 min",
    "contenu": "<p>Pour donner l'heure, un âge, une date ou décrire un objet, il faut connaître les <b>nombres</b>, les <b>jours</b>, les <b>mois</b> et les <b>couleurs</b>.</p><div class='definition'><b>Les nombres de 1 à 10 :</b> one, two, three, four, five, six, seven, eight, nine, ten.<br><b>De 11 à 20 :</b> eleven, twelve, thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty.<br><b>Les dizaines :</b> twenty, thirty, forty, fifty, sixty, seventy, eighty, ninety, one hundred.</div><p><b>Les jours :</b> Monday (lundi), Tuesday (mardi), Wednesday (mercredi), Thursday (jeudi), Friday (vendredi), Saturday (samedi), Sunday (dimanche).</p><p><b>Les mois :</b> January (janvier), February (février), March (mars), April (avril), May (mai), June (juin), July (juillet), August (août), September (septembre), October (octobre), November (novembre), December (décembre).</p><p><b>Les couleurs :</b> red (rouge), blue (bleu), green (vert), yellow (jaune), white (blanc), black (noir), orange, brown (marron).</p><div class='exemple'><b>Exemple :</b> <i>I am twelve years old. The school starts on Monday, in September. My bag is blue.</i> (J'ai douze ans. L'école commence le lundi, en septembre. Mon sac est bleu.)</div><div class='astuce'><b>Astuce :</b> en anglais, les jours et les mois prennent une majuscule. On écrit <i>Monday</i> et non <i>monday</i>, <i>January</i> et non <i>january</i>.</div>",
