    "titre": "Les droits de l'enfant",
    "duree": "40 min",
    "contenu": "<p>Tout enfant, quels que soient son origine, sa religion ou son sexe, a des <b>droits</b>. Ces droits sont reconnus par la Convention internationale des droits de l'enfant, adoptée par l'ONU en 1989 et ratifiée par le Cameroun.</p><div class='definition'><b>Un droit</b> est ce qu'une personne peut légitimement exiger pour vivre dignement.<br><b>Une obligation</b> est ce qu'une personne doit faire vis-à-vis des autres.</div><p>Parmi les droits essentiels de l'enfant, on trouve : le droit à la vie, le droit à un nom et à une nationalité (l'acte de naissance), le droit à l'éducation, le droit à la santé, le droit d'être protégé contre la violence et le droit d'être écouté.</p><div class='exemple'><b>Exemple :</b> tout enfant a le droit d'aller à l'école. En même temps, il a l'obligation de respecter les règles de l'établissement et les camarades.</div><div class='astuce'><b>Astuce :</b> chaque droit a une contrepartie : quand tu as un droit, les autres ont l'obligation de le respecter. Le droit à l'éducation oblige les parents et l'État à t'offrir une école.</div>",
