    "id": "e6-regles-vie-scolaire",
    "titre": "Le règlement intérieur et la vie scolaire",
    "duree": "40 min",
    "contenu": "<p>Pour vivre ensemble dans un établissement, il faut des <b>règles</b>. Elles sont rassemblées dans le <b>règlement intérieur</b>, que chaque élève et chaque parent doit connaître.</p><div class='definition'><b>Le règlement intérieur</b> est l'ensemble des règles qui organisent la vie de l'établissement : horaires, tenue, comportement, respect du matériel, sécurité.<br><b>Un sanction</b> est une mesure prise en cas de non-respect du règlement. Elle doit être juste et proportionnée à la faute.</div><p>Les règles servent à protéger chacun : elles garantissent le travail, la sécurité et le respect entre élèves et adultes.</p><div class='exemple'><b>Exemple :</b> arriver à l'heure en classe est une règle. Elle permet de ne pas déranger le cours et de respecter le travail du professeur et des camarades.</div><div class='astuce'><b>Astuce :</b> pour comprendre une règle, demande-toi à quoi elle sert : protéger qui ? éviter quel problème ? Une règle a toujours une raison.</div>",
