    "duree": "40 min",
    "contenu": "<p>Dans une société, les personnes ne pensent pas toutes de la même façon. Pour vivre ensemble, il faut savoir <b>dialoguer</b> et <b>respecter les différences</b>.</p><div class='definition'><b>Le dialogue</b> est l'échange d'idées entre personnes, dans le calme, en écoutant l'autre.<br><b>La tolérance</b> est l'acceptation de ce qui est différent de soi : langue, religion, origine, opinion.<br><b>La discrimination</b> est un traitement injuste d'une personne à cause de ses différences. Elle est interdite par la loi.</div><p>Refuser de se moquer d'un camarade qui parle une autre langue, c'est pratiquer la tolérance. Écouter avant de répondre, c'est pratiquer le dialogue.</p><div class='exemple'><b>Exemple :</b> dans une classe, des élèves parlent le français, le fulfulde ou l'ewondo. Accepter cette diversité, c'est une richesse pour tous.</div><div class='astuce'><b>Astuce :</b> avant de juger une personne, pose-toi la question : est-ce que je la respecte si elle est différente de moi ? Le dialogue commence par l'écoute.</div>",
