    "duree": "40 min",
    "contenu": "<p>Avant toute activité sportive, on doit <b>s'échauffer</b>. L'échauffement prépare le corps à l'effort et réduit les risques de blessure.</p><div class='definition'><b>L'échauffement</b> est une série d'exercices légers (marche, course lente, étirements doux) qui augmente progressivement la température du corps et la fréquence cardiaque.<br><b>Le retour au calme</b> est une phase de marche lente et d'étirements après l'effort, pour permettre au corps de récupérer.</div><p>Pendant l'effort, le cœur bat plus vite et la respiration s'accélère. C'est normal. Mais il faut s'arrêter en cas de douleur, de vertige ou d'essoufflement excessif.</p><div class='exemple'><b>Exemple :</b> avant un match de football, on commence par 5 minutes de course lente, puis des petits mouvements de jambes et de bras. Après le match, on marche doucement et on s'étire.</div><div class='astuce'><b>Astuce :</b> une bonne séance suit toujours trois temps : échauffement, activité principale, retour au calme. Ne saute jamais l'échauffement.</div>",
