    "titre": "La course et l'endurance",
    "duree": "40 min",
    "contenu": "<p>La <b>course</b> est une activité de base. Elle développe la <b>vitesse</b>, la <b>résistance</b> et l'<b>endurance</b>, c'est-à-dire la capacité à tenir un effort longtemps.</p><div class='definition'><b>La vitesse</b> est la capacité à parcourir une distance courte le plus vite possible (ex. : 60 m).<br><b>L'endurance</b> est la capacité à maintenir un effort modéré sur une longue durée (ex. : 1 000 m).<br><b>Le rythme</b> est la régularité de la course : courir à une allure que l'on peut tenir.</div><p>Pour bien courir, il faut adapter son allure à la distance : on part plus vite pour un sprint, et plus régulièrement pour une course longue.</p><div class='exemple'><b>Exemple :</b> lors d'une course de 800 m, on ne part pas à fond. On garde un rythme régulier, puis on accélère dans le dernier tour.</div><div class='astuce'><b>Astuce :</b> pour progresser en endurance, cours régulièrement à une allure où tu peux encore parler. Si tu ne peux plus parler, tu vas trop vite.</div>",
