    "titre": "Les jeux collectifs : coopération et fair-play",
    "duree": "40 min",
    "contenu": "<p>Les <b>jeux collectifs</b> (football, handball, basket-ball, ballon au pied) se pratiquent en équipe. Ils demandent de la coopération, de la communication et le respect des règles.</p><div class='definition'><b>La coopération</b> est le travail commun vers un même objectif.<br><b>Le fair-play</b> est l'attitude loyale : respecter les règles, l'adversaire et l'arbitre, accepter la défaite comme la victoire.<br><b>Un rôle</b> est une fonction dans l'équipe : attaquant, défenseur, gardien, capitaine.</div><p>Dans un jeu collectif, chacun a un rôle utile. Un joueur seul ne gagne pas un match : c'est le travail de l'équipe qui compte.</p><div class='exemple'><b>Exemple :</b> au football, le défenseur protège le but, le milieu fait circuler le ballon et l'attaquant marque. Si l'un ne fait pas son rôle, l'équipe est déséquilibrée.</div><div class='astuce'><b>Astuce :</b> le fair-play, c'est aussi : serrer la main de l'adversaire à la fin du match, quel que soit le résultat.</div>",
