    "duree": "40 min",
    "contenu": "<p>La pratique sportive améliore la santé, à condition de respecter quelques règles d'<b>hygiène</b> et d'<b>alimentation</b>.</p><div class='definition'><b>L'hygiène corporelle</b> comprend la douche après l'effort, le port de vêtements propres et secs, et le lavage des mains.<br><b>L'hydratation</b> est le fait de boire régulièrement de l'eau, surtout par temps chaud, avant, pendant et après l'effort.<br><b>Le repos</b> permet au corps de récupérer : un sommeil suffisant est indispensable.</div><p>Il faut éviter de manger un repas lourd juste avant de courir. Un repas léger, pris environ deux heures avant l'effort, est préférable.</p><div class='exemple'><b>Exemple :</b> avant un cours de sport à midi, on évite un plat très gras et on boit de l'eau. Après l'effort, on se lave et on prend un repas équilibré.</div><div class='astuce'><b>Astuce :</b> pour savoir si tu bois assez, regarde la couleur de tes urines : si elles sont très foncées, tu dois boire davantage.</div>",
