    "titre": "Se repérer sur la carte : latitude et longitude",
    "duree": "40 min",
    "contenu": "<p>Pour trouver un lieu sur la Terre, on utilise un <b>système de coordonnées</b> : la <b>latitude</b> et la <b>longitude</b>, mesurées en degrés.</p><div class='definition'><b>L'équateur</b> est le cercle imaginaire qui sépare la Terre en deux hémisphères : nord et sud. Il correspond à la latitude 0°.<br><b>La latitude</b> mesure la distance au nord ou au sud de l'équateur (de 0° à 90°).<br><b>Le méridien de Greenwich</b> est la ligne de référence de la longitude : longitude 0°.<br><b>La longitude</b> mesure la distance à l'est ou à l'ouest du méridien de Greenwich (de 0° à 180°).</div><div class='exemple'><b>Exemple :</b> Yaoundé se trouve à environ 4° de latitude nord, ce qui veut dire qu'elle est au nord de l'équateur. Le Cameroun est donc dans l'hémisphère nord.</div><div class='astuce'><b>Astuce :</b> pour la latitude, pense à la lettre N (nord) ou S (sud). Pour la longitude, pense à E (est) ou O (ouest). Tu peux aussi retenir : l'équateur est l'horizontale, le méridien de Greenwich est la verticale.</div>",
