    "id": "g6-relief-cameroun",
    "titre": "Le relief du Cameroun",
    "duree": "40 min",
    "contenu": "<p>Le <b>relief</b> désigne l'ensemble des formes de la surface terrestre : montagnes, plateaux, plaines, vallées. Le Cameroun présente une grande variété de reliefs.</p><div class='definition'><b>Une montagne</b> est une élévation importante du sol.<br><b>Un plateau</b> est une étendue élevée et relativement plate.<br><b>Une plaine</b> est une étendue basse et plate.</div><p>Au Cameroun, on distingue plusieurs grands ensembles :</p><ul><li>le <b>mont Cameroun</b>, un volcan actif au sud-ouest, qui culmine à environ 4 100 m ;</li><li>les <b>hauts plateaux de l'Ouest</b>, appelés les Grassfields ;</li><li>le <b>plateau de l'Adamaoua</b>, au centre du pays ;</li><li>les <b>plaines côtières</b> du littoral, comme autour de Douala ;</li><li>les <b>plaines du Nord</b>, vers le lac Tchad.</li></ul><div class='exemple'><b>Exemple :</b> le mont Cameroun est le plus haut sommet d'Afrique de l'Ouest, et l'un des volcans les plus actifs du continent.</div><div class='astuce'><b>Astuce :</b> pour te souvenir du relief, pense au Cameroun en « escalier » : plaines côtières au sud-ouest, plateaux au centre et à l'ouest, plaines du Nord.</div>",
