    "duree": "40 min",
    "contenu": "<p>Le <b>climat</b> est l'ensemble des conditions de température et de pluie observées sur une longue période dans un lieu. Le Cameroun présente plusieurs types de climats, selon sa latitude et son relief.</p><div class='definition'><b>Climat équatorial :</b> chaud et très humide toute l'année, au sud du pays (forêt).<br><b>Climat tropical de type soudanien :</b> une saison sèche et une saison des pluies bien marquées, au centre et au nord.<br><b>Climat de montagne :</b> plus frais, en altitude, comme sur les hauts plateaux de l'Ouest.</div><p>Dans le sud du pays, on connaît deux saisons des pluies (grande et petite saison des pluies) séparées par deux saisons sèches. Dans le nord, il n'y a qu'une saison des pluies et une saison sèche.</p><div class='exemple'><b>Exemple :</b> à Maroua, au nord, la saison des pluies dure quelques mois, et la saison sèche est longue. À Douala, au sud, il pleut presque toute l'année.</div><div class='astuce'><b>Astuce :</b> pour distinguer les climats, pense à la latitude (plus on va vers le nord, plus la saison sèche est longue) et à l'altitude (plus on monte, plus il fait frais).</div>",
