    "duree": "40 min",
    "contenu": "<p>L'<b>Histoire</b> commence avec l'invention de l'écriture, vers 3300 avant notre ère. Ce qui s'est passé avant est la <b>Préhistoire</b> : on la connaît grâce aux fossiles, aux outils et aux peintures laissés par les hommes.</p><div class='definition'><b>Le Paléolithique</b> (âge de la pierre taillée) : les hommes sont chasseurs-cueilleurs. Ils vivent de la chasse et de la cueillette et se déplacent au gré des saisons.<br><b>Le Néolithique</b> (âge de la pierre polie) : les hommes deviennent sédentaires. Ils pratiquent l'agriculture et l'élevage et fabriquent de la poterie.</div><p>En Afrique, des sites comme ceux de la vallée du Rift ou du Sahara ont livré de nombreux outils et des peintures rupestres.</p><div class='exemple'><b>Exemple :</b> un biface, outil en pierre taillée des deux côtés, servait à découper la viande et à travailler le bois. Une poterie, elle, servait à stocker et cuire les aliments.</div><div class='astuce'><b>Astuce :</b> retiens la logique : paléo = ancien (pierre taillée, chasse), néo = nouveau (pierre polie, agriculture).</div>",
