    "duree": "40 min",
    "contenu": "<p>L'<b>Égypte ancienne</b> est l'une des premières grandes civilisations. Elle s'est développée le long du <b>Nil</b>, un fleuve qui inonde régulièrement les terres et les rend fertiles.</p><div class='definition'><b>Pharaon :</b> roi de l'Égypte ancienne, considéré comme le représentant des dieux sur terre.<br><b>Pyramide :</b> tombeau monumental construit pour les pharaons, par exemple à Gizeh.<br><b>Hiéroglyphes :</b> écriture de l'Égypte ancienne, faite de signes représentant des sons, des mots ou des idées.</div><p>Le Nil permet l'agriculture : on cultive le blé, l'orge et le lin. L'Égypte est organisée en un pouvoir fort, avec des scribes qui savent écrire et compter.</p><div class='exemple'><b>Exemple :</b> les pyramides de Gizeh, construites il y a environ 4 500 ans, montrent la puissance du pharaon et l'organisation du travail.</div><div class='astuce'><b>Astuce :</b> retiens le lien : le Nil fournit l'eau, donc l'agriculture, donc la richesse et la civilisation.</div>",
