    "titre": "Découvrir l'ordinateur : matériel et logiciel",
    "duree": "40 min",
    "contenu": "<p>Un <b>ordinateur</b> est une machine qui reçoit des informations, les traite et produit des résultats. Il fonctionne grâce à deux ensembles : le <b>matériel</b> et le <b>logiciel</b>.</p><div class='definition'><b>Le matériel (hardware)</b> est la partie physique que l'on peut toucher : écran, clavier, souris, unité centrale, disque dur.<br><b>Le logiciel (software)</b> est l'ensemble des programmes qui donnent des instructions à la machine : système d'exploitation, traitement de texte, navigateur.</div><p>On distingue les <b>périphériques d'entrée</b> (clavier, souris, micro, scanner), qui envoient des informations à l'ordinateur, et les <b>périphériques de sortie</b> (écran, imprimante, haut-parleurs), qui affichent ou restituent les résultats.</p><div class='exemple'><b>Exemple :</b> quand tu tapes un texte au clavier, le clavier est un périphérique d'entrée. Le texte apparaît à l'écran, qui est un périphérique de sortie. Le logiciel de traitement de texte permet d'écrire.</div><div class='astuce'><b>Astuce :</b> pour savoir si un élément est matériel ou logiciel, demande-toi : est-ce que je peux le toucher ? Si oui, c'est du matériel. Sinon, c'est du logiciel.</div>",
