    "titre": "Introduction à l'algorithme",
    "duree": "40 min",
    "contenu": "<p>Un <b>algorithme</b> est une suite d'instructions précises et ordonnées qui permet de résoudre un problème ou de réaliser une tâche. Tu utilises des algorithmes tous les jours, sans le savoir.</p><div class='definition'><b>Un algorithme</b> est une suite d'étapes claires, dans un ordre précis, qui mène à un résultat.<br><b>Une instruction</b> est une action simple (prendre, poser, ajouter).<br><b>Un programme</b> est un algorithme écrit dans un langage que l'ordinateur comprend.</div><p>Un bon algorithme est <b>précis</b> (chaque étape est claire), <b>ordonné</b> (les étapes se suivent dans le bon ordre) et <b>fini</b> (il s'arrête au bout d'un moment).</p><div class='exemple'><b>Exemple :</b> recette du thé : 1) mettre de l'eau dans la bouilloire ; 2) faire chauffer l'eau ; 3) mettre le sachet dans la tasse ; 4) verser l'eau chaude ; 5) attendre 3 minutes ; 6) retirer le sachet.</div><div class='astuce'><b>Astuce :</b> si tu changes l'ordre des étapes, le résultat peut être différent. Verser l'eau avant de la chauffer ne donne pas le même thé !</div>",
