    "titre": "La numération : grands nombres et valeur des chiffres",
    "duree": "40 min",
    "contenu": "<p>Notre système de numération est <b>décimal</b> : chaque chiffre a une valeur qui dépend de sa <b>position</b> dans le nombre. En partant de la droite, on trouve les unités, les dizaines, les centaines, puis les milliers, les dizaines de milliers, les centaines de milliers et les millions.</p><div class='definition'><b>Définition :</b> la <b>valeur d'un chiffre</b> est le chiffre multiplié par la valeur de sa position. Dans 4 528, le 5 vaut 5 centaines, soit 500.</div><div class='exemple'><b>Exemple :</b> 4 528 = 4 × 1 000 + 5 × 100 + 2 × 10 + 8 × 1. C'est la <b>décomposition</b> du nombre.</div><p>Pour lire un grand nombre, on le sépare en tranches de trois chiffres en partant de la droite. Ainsi 25 307 se lit « vingt-cinq mille trois cent sept ».</p><div class='astuce'><b>Astuce :</b> pour comparer deux nombres, celui qui a le plus de chiffres est le plus grand (si le premier chiffre n'est pas un zéro). Si les deux ont le même nombre de chiffres, on compare chiffre par chiffre en partant de la gauche.</div><p>Les nombres 1 000 000 (un million) et 10 000 (dix mille) sont très utilisés : pense aux populations, aux distances et aux prix.</p>",
