    "contenu": "<p>Deux grandeurs servent à décrire une figure :</p><div class='definition'><b>Périmètre :</b> la longueur tout autour de la figure (son contour). Il s'exprime en cm, m, km.<br><b>Aire :</b> la surface de la figure. Elle s'exprime en cm², m², km².</div><p><b>Formules à connaître :</b></p><ul><li>Rectangle de longueur L et de largeur l : périmètre = 2 × (L + l) ; aire = L × l.</li><li>Carré de côté c : périmètre = 4 × c ; aire = c × c.</li><li>Triangle de base b et de hauteur h : aire = b × h ÷ 2.</li></ul><div class='exemple'><b>Exemple :</b> un rectangle de 8 cm sur 3 cm. Périmètre = 2 × (8 + 3) = 22 cm. Aire = 8 × 3 = 24 cm².</div><div class='astuce'><b>Astuce :</b> ne confonds pas les unités. Un périmètre se mesure en cm, une aire en cm². Une aire de 1 cm² est un carré dont chaque côté mesure 1 cm.</div>",
