    "titre": "Les trois états de la matière",
    "duree": "40 min",
    "contenu": "<p>Tout ce qui nous entoure est constitué de <b>matière</b>. La matière existe sous trois <b>états</b> : solide, liquide et gazeux.</p><div class='definition'><b>Solide :</b> il a une forme propre et un volume propre. Ex. : une pierre, une craie.<br><b>Liquide :</b> il n'a pas de forme propre (il prend la forme du récipient) mais il a un volume propre. Ex. : l'eau, l'huile.<br><b>Gaz :</b> il n'a ni forme propre ni volume propre : il occupe tout l'espace disponible. Ex. : l'air, la vapeur d'eau.</div><p>La matière peut <b>changer d'état</b> quand on la chauffe ou la refroidit :</p><ul><li><b>fusion</b> : solide → liquide (la glace fond) ;</li><li><b>vaporisation</b> : liquide → gaz (l'eau bout) ;</li><li><b>solidification</b> : liquide → solide (l'eau devient glace au congélateur) ;</li><li><b>condensation</b> : gaz → liquide (la buée sur un verre froid).</li></ul><div class='exemple'><b>Exemple :</b> un glaçon posé sur une table fond et devient de l'eau. Si on chauffe cette eau, elle se transforme en vapeur.</div><div class='astuce'><b>Astuce :</b> pour te souvenir des changements d'état, pense au sens du mot : la fusion, c'est fondre ; la vaporisation, c'est passer en vapeur.</div>",
