    "matiere": "Physique-Chimie",
    "id": "pc6-solutions",
    "titre": "Les solutions et la dissolution",
    "duree": "40 min",
    "contenu": "<p>Lorsqu'on verse du sucre dans de l'eau et qu'on remue, le sucre disparaît : il s'est <b>dissous</b>. Le mélange obtenu est une <b>solution</b>.</p><div class='definition'><b>Solvant :</b> le liquide qui dissout (ici l'eau).<br><b>Soluté :</b> la substance qui se dissout (ici le sucre).<br><b>Solution :</b> le mélange homogène obtenu : solvant + soluté.</div><p>Une solution est <b>homogène</b> : on ne voit plus les grains de sucre ou de sel. Un soluté a une <b>limite de dissolution</b> : au-delà, il reste des grains au fond. On dit alors que la solution est saturée.</p><div class='exemple'><b>Exemple :</b> le jus de bissap ou de gingembre est une solution : le sucre est dissous dans l'eau. Le sirop est une solution très concentrée.</div><div class='astuce'><b>Astuce :</b> pour dissoudre plus vite un solide dans un liquide, on peut remuer, ou chauffer le liquide (sauf cas particulier) : le soluté se dissout plus facilement.</div>",
