    "contenu": "<p>En sciences, on mesure des grandeurs. Deux grandeurs importantes en 6ème sont la <b>masse</b> et le <b>volume</b>.</p><div class='definition'><b>La masse</b> mesure la quantité de matière d'un objet. Elle se mesure avec une balance et s'exprime en <b>gramme (g)</b> ou en <b>kilogramme (kg)</b>.<br><b>Le volume</b> mesure l'espace occupé par un objet. Pour un liquide, on utilise une éprouvette graduée ou un récipient gradué. Unités : <b>millilitre (mL)</b> et <b>litre (L)</b>.</div><p><b>Conversions à connaître :</b></p><ul><li>1 kg = 1 000 g</li><li>1 L = 1 000 mL</li><li>1 mL = 1 cm³</li></ul><div class='exemple'><b>Exemple :</b> un sac de riz de 2 kg contient 2 000 g. Une bouteille de 1,5 L contient 1 500 mL.</div><div class='astuce'><b>Astuce :</b> pour convertir des kilogrammes en grammes, on multiplie par 1 000 (ou on déplace la virgule de 3 rangs vers la droite). Pour des millilitres en litres, on divise par 1 000.</div>",
