    "titre": "Les caractéristiques des êtres vivants",
    "duree": "40 min",
    "contenu": "<p>Autour de nous, certains objets sont <b>vivants</b> (un arbre, un chien, un enfant) et d'autres ne le sont pas (une pierre, une table, l'eau d'une bouteille). Pour les distinguer, on observe ce qu'un être vivant est capable de faire.</p><div class='definition'><b>Les êtres vivants ont les fonctions suivantes :</b><br>- la <b>nutrition</b> : ils se nourrissent et utilisent leur nourriture pour grandir et fonctionner ;<br>- la <b>respiration</b> : ils échangent des gaz avec le milieu (ils consomment du dioxygène et rejettent du dioxyde de carbone) ;<br>- la <b>reproduction</b> : ils donnent naissance à des individus semblables à eux ;<br>- la <b>relation avec le milieu</b> : ils réagissent à leur environnement (lumière, chaleur, danger).</div><p>Un être vivant <b>naît</b>, <b>grandit</b>, <b>se reproduit</b> et <b>meurt</b>. Il a besoin d'eau, d'air, de nourriture et d'une température convenable.</p><div class='exemple'><b>Exemple :</b> une plante pousse vers la lumière : c'est une réaction au milieu. Une pierre ne grandit pas et ne se nourrit pas : elle n'est donc pas vivante.</div><div class='astuce'><b>Astuce :</b> pour savoir si quelque chose est vivant, cherche s'il ou elle se nourrit, respire, se reproduit ou grandit. Il suffit souvent d'une seule de ces réponses négatives pour conclure qu'un objet n'est pas vivant... mais un être vivant doit les avoir toutes.</div>",
