    "id": "s6-besoins-plantes",
    "titre": "Les besoins et la nutrition des plantes vertes",
    "duree": "40 min",
    "contenu": "<p>Une plante verte fabrique elle-même sa nourriture. Elle a besoin de <b>eau</b> et de <b>sels minéraux</b>, puisés dans le sol par les racines, de <b>dioxyde de carbone</b> de l'air, capté par les feuilles, et de <b>lumière</b>.</p><div class='definition'><b>La photosynthèse</b> est la fabrication de sucre (matière organique) par la plante, grâce à la lumière et à la <b>chlorophylle</b>, le pigment vert des feuilles.<br>Bilan simplifié : eau + sels minéraux + dioxyde de carbone + lumière → matière organique (sucre) + <b>dioxygène rejeté</b>.</div><div class='exemple'><b>Exemple :</b> une plante placée dans une pièce sans lumière jaunit et ne grandit plus : elle ne peut pas fabriquer son sucre. C'est la preuve que la lumière est indispensable.</div><p>Les plantes sont des <b>producteurs</b> : elles fabriquent leur matière organique. Elles sont à la base de la chaîne alimentaire, car les animaux se nourrissent directement ou indirectement d'elles.</p><div class='astuce'><b>Astuce :</b> retiens le trajet de la nourriture de la plante : les racines prennent l'eau et les sels minéraux, les feuilles prennent le dioxyde de carbone et la lumière, et la plante rejette du dioxygène.</div>",
