    "contenu": "<p>Pour vivre, l'être humain doit manger. Les aliments contiennent des <b>nutriments</b>, des substances utiles à l'organisme.</p><div class='definition'><b>Les grandes familles de nutriments :</b><br>- les <b>glucides</b> (riz, manioc, maïs, banane plantain, mil) : ils donnent de l'<b>énergie</b> ;<br>- les <b>lipides</b> (huile, arachide, beurre de karité, poisson gras) : ils fournissent de l'énergie en réserve ;<br>- les <b>protéines</b> (viande, poisson, œuf, haricot, soja) : elles servent à <b>construire et réparer</b> le corps ;<br>- les <b>vitamines</b> et les <b>sels minéraux</b> (fruits, légumes) : ils <b>protègent</b> et régulent le fonctionnement de l'organisme ;<br>- l'<b>eau</b> : indispensable, elle permet de réguler la température et de transporter les substances.</div><div class='exemple'><b>Exemple :</b> un repas équilibré au Cameroun peut associer du manioc (glucides), du poisson (protéines), des légumes comme la morelle ou les feuilles de manioc (vitamines et sels minéraux) et de l'huile de palme ou d'arachide (lipides).</div><p>Une alimentation <b>équilibrée</b> apporte tous ces nutriments en quantités suffisantes. Une alimentation déséquilibrée peut provoquer des maladies, par manque ou par excès.</p><div class='astuce'><b>Astuce :</b> pour vérifier l'équilibre d'un repas, cherche la présence des trois familles : une source d'énergie (glucides ou lipides), une source de construction (protéines) et une source de protection (fruits et légumes).</div>",
